// Üretilen dosya: tool/ozgun/uret.py. Yabancı Dil · Dünya alfabeleri, yazı sistemleri tarihi, etimoloji ve çeviri bilimi (Fenike, Kiril, Göktürk, Uygur, Hangıl, hiyeroglif, yalancı eşdeğerler, ödünçleme) (zor).
const ozLanguage18Zor = <(String, String, List<String>, String)>[
  ('Dilbilimci Peter T. Daniels tarafından tanımlanan "abugida" yazı sistemini "hece yazısı"ndan (sillabary) ayıran temel özellik nedir?', 'Abugidada aynı ünsüzle başlayan hecelerin ortak bir temel ünsüz harfi taşıyıp ünlülerin buna düzenli eklerle bağlanması', ['Hece yazısında yalnızca sessiz harflerin bulunması, abugidada ise sadece sesli harflerin yer alması', 'Abugidanın yalnızca sağdan sola yazılması, hece yazısının ise yalnızca yukarıdan aşağıya yazılması', 'Hece yazısında her kelimenin ayrı bir resimle çizilmesi, abugidada ise Latin harflerinin kullanılması'], 'Saf hece yazısında "ka" ve "ki" sembolleri birbirine hiç benzemezken, abugidada "k" tabanı korunur ve ünlüler sistematik işaretlerle değiştirilir.'),
  ('Çivi yazısı ve Mısır hiyerogliflerinde okunmayan ancak kelimenin hangi anlam kategorisine (tanrı, şehir, bitki vb.) ait olduğunu gösteren sessiz işaretlere ne denir?', 'Determinatif', ['Matres lectionis', 'Virama', 'Furigana'], 'Determinatifler (belirleyiciler), eşsesli veya çok anlamlı kelimelerin anlam bulanıklığını gidermek için eklenen okunmaz sınıflandırıcı işaretlerdir.'),
  ('Harf şekillerinin, temsil ettikleri nesnenin o dildeki adının ilk sesiyle eşleştirilmesi ilkesine (örneğin "öküz" anlamına gelen \'alef\' resminin /ʔ/ sesini vermesi) ne ad verilir?', 'Akrofoni ilkesi', ['Boustrophedon ilkesi', 'fonetik tümleme ilkesi', 'Ünlü uyumu ilkesi'], 'Akrofoni ilkesi, piktografik bir sembolün adının baş sesini temsil edecek biçimde harfe dönüşmesini sağlayan mekanizmadır.'),
  ('Arami yazısının Orta Doğu ve Asya yazı tarihinde Fenike yazısından bile daha geniş bir coğrafyada ata yazı haline gelmesinin temel tarihsel nedeni nedir?', 'Yeni Asur ve Pers (Ahameniş) İmparatorluklarının resmi diplomasi ve idare dili/yazısı olarak benimsenmesi', ['İskender\'in fetihleriyle birlikte tüm Hindistan ve Çin tapınaklarında zorunlu ibadet yazısı ilan edilmesi', 'Matbaanın icadından önce metal harflerle basılabilen tek antik Sami yazı sistemi olması', 'Hem ünlü hem ünsüz sesleri noktalama işaretleriyle eksiksiz gösteren ilk sistem olması'], 'Aramice ve Arami ebcedi, Mezopotamya\'dan İndus Vadisi\'ne uzanan imparatorlukların ortak bürokrasi aracı (lingua franca) olmuş; İbrani, Arap, Süryani ve Brahmi/Kharosthi kollarını etkilemiştir.'),
  ('Suriye kıyısındaki Ras Şamra\'da keşfedilen ve kil tabletler üzerine çivi yazısı tekniğiyle kazınan 30 harfli antik Sami ebcedi hangisidir?', 'Ugarit yazısı', ['Nebati yazısı', 'Güney Arabistan Müsned yazısı', 'Süryani Estrangelo yazısı'], 'MÖ 14-12. yüzyıllara ait Ugarit yazısı, görünüm olarak Mezopotamya çivi yazısına benzese de yapıca 30 harflik bir Sami ebcedidir.'),
  ('Yunanlılar Fenike yazısını kendi Hint-Avrupa dillerine uyarlarken ünlü harfleri nasıl oluşturmuşlardır?', 'Yunancada karşılığı bulunmayan gırtlak ünsüzlerine ait Fenike harflerini ünlü seslere tahsis ederek', ['Mısır hiyerogliflerinden beş adet yeni kuş sembolü kopyalayıp alfabenin sonuna ekleyerek', 'Her ünsüz harfin altına küçük çizgiler ve daireler koyup hece tabanlı bir sistem kurarak', 'Girit\'teki Linear B hece yazısından aldıkları ünlü işaretlerini Fenike harfleriyle birleştirerek'], 'Fenike dilindeki \'alef, he, yod, ayin gibi Yunancada fonemik karşılığı olmayan ünsüz harfler A, E, I, O ünlülerini göstermek üzere yeniden işlevlendirilmiştir.'),
  ('Erken dönem Latin alfabesinde "C" harfinin hem /k/ hem de /g/ sesini karşılaması hangi dilsel aracılığın sonucudur?', 'Etrüsk dilinde ötümlü (/g/) ve ötümsüz (/k/) patlayıcı ünsüz ayrımının bulunmaması', ['Fenike yazısında /g/ sesini gösteren Gimel harfinin hiçbir zaman var olmaması', 'Romalıların /g/ sesini yalnızca Yunancadan geçen felsefe terimlerinde telaffuz etmesi', 'Klasik Latincede tüm gırtlak ve damak ünsüzlerinin zamanla düşerek sessizleşmesi'], 'Etrüskçede /g/ fonemi olmadığı için Yunan Gamma harfi /k/ sesiyle de kullanılmış; Romalılar daha sonra /g/ için C\'ye bir çizgi ekleyerek G harfini icat etmiştir.'),
  ('Aziz Kiril ve Metodius\'un Eski Kilise Slavcası için bizzat icat ettikleri, Kiril alfabesinden bile daha eski olan ilk Slav alfabesi aşağıdakilerden hangisidir?', 'Glagol alfabesi', ['Ogham alfabesi', 'Soğd alfabesi', 'Kıpti alfabesi'], 'Aziz Kiril\'in 862-863 yıllarında Moravya misyonu için doğrudan tasarladığı özgün alfabe Glagol (Glagolitik) alfabesidir; Kiril alfabesi ise öğrencileri tarafından Yunan unsiyal yazısına yaklaştırılarak oluşturulmuştur.'),
  ('İslam hat ve yazı tarihinde, birbirine benzeyen harfleri (örneğin ب, ت, ث) ayırt etmek için noktaların (i\'cam) ve sesli işaretlerin sistematikleşmesine öncülük eden dilciler kimlerdir?', 'Ebü\'l-Esved ed-Düeli ve Halil bin Ahmed', ['İbn Haldun ve İbn بطuta', 'Farabi ve İbn Sina', 'Sibaveyh ve Zemahşeri'], 'İlk harekeleme noktalarını Ebü\'l-Esved ed-Düeli başlatmış, bugünkü modern hareke sistemini ise 8. yüzyılda Halil bin Ahmed el-Ferahidi düzenlemiştir.'),
  ('İbranicede Tevrat metinlerinin doğru okunuşunu korumak amacıyla Orta Çağ\'da Taberiye\'deki (Tiberias) bilginler tarafından geliştirilen ünlü noktalama sistemine ne ad verilir?', 'Nikud', ['Katakana', 'Devanagari', 'Hangıl'], 'İbranicede "noktalama" anlamına gelen Nikud sistemi, Masoret bilginleri tarafından ünsüz metne ünlü ses değerlerini eklemek için geliştirilmiştir.'),
  ('Arap ve İbrani yazılarının her ikisi de Arami kökenli ebcedler olmasına rağmen görsel yapılarındaki en belirgin tipografik fark nedir?', 'Arap yazısının kelime içinde harfleri birbirine bağlayan bitişik (kursif) yapıda olması, standart İbrani kare yazısında ise harflerin ayrı durması', ['İbrani yazısının soldan sağa doğru dizilmesi, Arap yazısının ise yukarıdan aşağıya doğru sütunlar halinde inmesi', 'Arap yazısında büyük ve küçük harf ayrımının bulunması, İbrani yazısında ise yalnızca küçük harflerin yer alması', 'İbrani yazısında her ünlü sesin zorunlu bağımsız bir harfi varken Arap yazısında hiçbir ünlünün gösterilememesi'], 'Matbu İbrani kare yazısında harfler birbirine bitişmezken, Arap yazısı el yazısında olduğu gibi matbaa dizgisinde de zorunlu olarak bitişik (ligatürlü) yazılır.'),
  ('İrlanda ve Britanya\'da MS 4-6. yüzyıllarda dikili taşların kenar köşeleri boyunca yatay ve eğik çentikler atılarak yazılan Erken Kelt alfabesi hangisidir?', 'Ogham alfabesi', ['Kıpti alfabesi', 'Gotik alfabe', 'Etrüsk alfabesi'], 'Ogham yazısı, dikey bir taş kenarını merkez çizgi kabul edip bunun sağına, soluna veya üzerine gruplar halinde çentikler kazıyarak harfleri gösteren özgün bir sistemdir.'),
  ('Türklerin tarih boyunca kullandığı Göktürk (Orhun), Uygur, Arap, Kiril ve Latin yazı sistemleri tipolojik olarak karşılaştırıldığında aşağıdakilerden hangisi söylenir?', 'Uygur ve Arap yazıları Arami/Soğd kökenli ünsüz ağırlıklı sistemlerken Kiril ve Latin tam fonemik alfabelerdir', ['Göktürk ve Latin yazıları Çinceden türetilmiş birer logogram sistemiyken Uygur yazısı saf bir abugidadır', 'Kiril ve Arap yazıları yukarıdan aşağıya doğru yazılan hece yazılarıyken Göktürk yazısı soldan sağa yazılan bir piktogramdır', 'Beş yazı sisteminin tamamı aynı yüzyılda Fenike denizcilerinden doğrudan kopyalanmış özdeş ebcedlerdir'], 'Uygur yazısı Soğd aracılığıyla Arami köküne, Arap yazısı Nebati aracılığıyla yine Arami köküne dayanırken; Kiril (Yunan üzerinden) ve Latin tam alfabe yapısındadır.'),
  ('Antik Yunan ve Erken Roma el yazmalarında kelimeler arasında boşluk veya noktalama işareti bırakmadan metni kesintisiz yazma geleneğine ne ad verilir?', 'Scriptio continua', ['Boustrophedon', 'Akrofoni', 'Allografi'], 'Latince "kesintisiz yazı" anlamına gelen scriptio continua, sesli okuma kültürünün hakim olduğu Antik Çağ\'da harflerin aralıksız dizilmesi uygulamasıdır.'),
  ('Fenike ebcedinin Mısır hiyeroglifleri ve Mezopotamya çivi yazısına kıyasla okuryazarlığın toplumda demokratikleşmesine yaptığı en büyük katkı nedir?', 'Yüzlerce karmaşık işaret yerine yirmi küsur harfle öğrenilebilmesi sayesinde yazıyı dar bir katipler sınıfının tekelinden çıkarması', ['İnsanların hiçbir eğitim almadan harflere baktıkları anda resmettikleri nesneleri doğrudan anlayabilmelerini sağlaması', 'Dünyadaki bütün dillerin tonlama ve vurgu özelliklerini tek bir sembolle kusursuzca kayıt altına alabilmesi', 'Kil tablet ve papirüs ihtiyacını ortadan kaldırarak yalnızca sözlü hafıza yoluyla aktarılabilmesi'], 'Binlerce logogram ve hece işareti yıllar süren katip okulu eğitimi gerektirirken, az sayıda işaretten oluşan alfabetik/ebced sistemler tüccar ve halk kesimlerinin hızla okuryazar olmasını sağlamıştır.'),
  ('Mısır\'da bulunan ve üzerinde hem hiyeroglif hem Demotik Mısır yazısı hem de Antik Yunanca metin yer aldığı için Jean-François Champollion\'un hiyeroglifleri çözmesini sağlayan eser hangisidir?', 'Rosetta Taşı (Reşid Taşı)', ['Behistun Yazıtı', 'Hammurabi Kanunları Steli', 'Moab Taşı (Meşa Steli)'], 'MÖ 196 tarihli Rosetta Taşı\'ndaki üç dilli/yazılı kararname, Champollion\'un kral adlarını (Ptolemaios, Kleopatra) çevreleyen kartuşlardan hareketle 1822\'de hiyerogliflerin fonetik yapısını çözmesini sağlamıştır.'),
  ('Mezopotamya çivi yazısının (Eski Farsça, Elamca ve Babilce/Akadca) Henry Rawlinson tarafından çözülmesinde anahtar rol oynayan İran\'daki üç dilli kaya anıtı hangisidir?', 'Behistun Yazıtı', ['Persepolis Kabartması', 'Nakş-ı Rüstem Anıtı', 'Karatepe Çift Dilli Yazıtı'], 'Pers Kralı I. Darius\'un Kirmanşah yakınlarındaki Behistun kayalıklarına kazıttığı üç dilli yazıt, çivi yazısı araştırmalarının "Rosetta Taşı" işlevini görmüştür.'),
  ('Güney Arabistan\'da Saba ve Himyer krallıklarının kullandığı antik "Müsned" yazısının Kuzey Sami (Fenike-Arami) kolundan ayrılan en önemli tarihsel mirası nedir?', 'Kızıldeniz üzerinden Afrika Boynuzu\'na geçerek Etiyopya\'daki Ge\'ez yazısının doğrudan atası olması', ['Batı Akdeniz\'e taşınarak İtalya\'daki Etrüsk ve Latin alfabelerinin doğuşunu sağlaması', 'Orta Asya bozkırlarına yayılarak Moğol ve Mançu dikey yazılarının temelini atması', 'Mısır hiyerogliflerinin yerini alarak Kıpti Hristiyan kilisesinin resmi alfabesi olması'], 'Güney Sami koluna ait Müsned ebcedi, anıtsal geometrik harfleriyle Afrika Boynuzu\'na geçmiş ve bugünkü Habeş (Ge\'ez) abugidasının temelini oluşturmuştur.'),
  ('Orta Asya üzerinden doğuya yayılan Soğd yazısını benimseyip 90 derece döndürerek yukarıdan aşağıya dikey sütunlar halinde yazan ve Mançu yazısına da kaynaklık eden yazı sistemi hangisidir?', 'Geleneksel Uygur-Moğol yazısı', ['Tibet hece-abugida yazısı', 'Eski Fars çivi yazısı', 'Gürcü Mhedruli alfabesi'], 'Cengiz Han döneminde Uygur katip Tata-Tonga aracılığıyla Moğollara geçen Eski Uygur yazısı, yukarıdan aşağıya ve soldan sağa dizilen dikey sütun yapısıyla Geleneksel Moğol ve Mançu yazılarını doğurmuştur.'),
  ('İran\'da Sasani İmparatorluğu döneminde Zerdüştlüğün kutsal kitabı Avesta\'yı en ince ses ayrıntılarıyla kaydetmek için Pehlevi ebcedinden türetilen "Din Dabireh" (Avesta) yazısının ayırt edici özelliği nedir?', 'Belirsiz Pehlevi ebcedinin aksine 50\'ye yakın harfle tüm ünlü ve ünsüz nüanslarını gösteren son derece zengin bir tam alfabe olması', ['Sadece rahiplerin anlayabileceği hayvan ve bitki resimlerinden oluşan gizli bir piktogram dizisi olması', 'Mezopotamya çivi yazısının 36 işaretlik son örneği olarak taş sütunlara kazınması', 'Kelimeleri hecelere bölmeden her bir dua cümlesini tek bir soyut ideogramla göstermesi'], 'Orta Farsçanın Pehlevi yazısı çok az harfle çok fazla sesi gösterdiği için belirsizdi; rahipler kutsal Avesta dualarının telaffuzu bozulmasın diye ondan son derece hassas fonetik bir tam alfabe türettiler.'),
  ('Sequoyah\'nın Çeroki yazısını tasarlarken Latin harflerine benzeyen "D, R, W, 4" gibi şekilleri sırasıyla "/a/, /e/, /la/, /se/" sesleri için kullanması yazı tarihi açısından neyi kanıtlar?', 'Görsel biçim ödünç alınsa bile yapısal sistemin (alfabeden hece yazısına) bağımsız olarak yeniden kurgulanabileceğini', ['Latin alfabesindeki bütün harflerin aslında tarih öncesi dönemde Amerika kıtasından Avrupa\'ya taşındığını', 'Hece yazılarının yalnızca İngilizce ve Fransızca gibi Hint-Avrupa dillerini yazmak için elverişli olduğunu', 'Hiçbir yazı sisteminin devlet baskısı ve üniversite kurulları olmadan toplum tarafından benimsenemeyeceğini'], 'Antropologların "stimulus diffusion" (uyaran yayılımı) dediği bu olayda Sequoyah, yazının "sesleri kağıda dökme" fikrini ve bazı görsel kalıpları görmüş ancak Latin alfabesini bilmediği için kendi diline uygun özgün bir hece sistemi kurmuştur.'),
  ('Osmanlı İmparatorluğu\'nda maliye, tapu ve defterdarlık kayıtlarında gizliliği ve hızı sağlamak amacıyla kullanılan noktaları atılmış özel bürokrasi yazısı hangisidir?', 'Siyakat', ['Celi Sülüs', 'Muhakkak', 'Reyhânî'], 'Siyakat yazısı, noktasız ve kısaltmalı yapısıyla dışarıdan kişilerin kolayca okuyup tahrif edemeyeceği bir maliye ve tapu sicil şifresi/yazısı işlevi görmüştür.'),
  ('Uygur yazısının Arap yazısıyla yer değiştirmesinden önce Moğol İmparatorluğu\'nda Kubilay Han\'ın Tibetli rahip Drogön Çögyal Phagpa\'ya hazırlattığı "Phags-pa" yazısının tarihsel amacı neydi?', 'İmparatorluktaki Çince, Moğolca, Türkçe ve Tibetçe gibi farklı dilleri tek bir evrensel devlet yazısıyla kaydedebilmek', ['Sadece Budist manastırlarındaki gizli büyü metinlerini halktan saklamak için şifreli resimler üretmek', 'Avrupa\'dan gelen Latin alfabesini taklit ederek Venedikli tüccarlarla gümrük antlaşmaları imzalamak', 'Kağıt kullanımını yasaklayıp tüm yasaları yeniden Sümer çivi yazısıyla kil tabletlere kazımak'], 'Tibet abugidasından türetilip Moğol yazısı gibi dikey sütunlar halinde yazılan kare Phags-pa yazısı (1269), çok uluslu Yuan Hanedanı\'nın tüm dillerini kapsayacak fonetik bir "imparatorluk yazısı" olarak tasarlanmış, Kore Hangıl harflerine de esin vermiştir.'),
  ('Latin alfabesindeki "F, U, V, W, Y" harflerinin tamamının soy ağacı izlendiğinde Fenike alfabesindeki hangi tek harfe uzandığı görülür?', 'Çengel veya çivi anlamına gelen Waw (𐤅) harfine', ['Ev anlamına gelen Bet (𐤁) harfine', 'Su anlamına gelen Mem (𐤌) harfine', 'Baş anlamına gelen Reş (𐤓) harfine'], 'Fenike Waw harfi erken Yunancaya Digamma (Ϝ -> Latince F) ve Upsilon (Υ -> Latince V, oradan U ve W; ayrıca klasik dönemde doğrudan Y) olarak iki kez/farklı evrelerde girmiş ve 5 ayrı Latin harfini doğurmuştur.'),
  ('Dünya üzerindeki bağımsız yazı icatları (sıfırdan yazının yaratılması) tarihçiler ve dilbilimciler tarafından değerlendirildiğinde aşağıdakilerden hangisi genel kabul görür?', 'Yazı tarihte Sümer, Mısır (tartışmalı bağımsız/etkileşimli), Çin ve Mezoamerika\'da birbirinden bağımsız çok az merkezde doğmuş, diğer tüm yazılar bunlardan yayılmıştır', ['Tarihte kurulan her devlet ve imparatorluk komşularından hiçbir fikir almadan kendi alfabesini sıfırdan icat etmiştir', 'Yeryüzündeki bütün yazı sistemleri MÖ 1. yüzyılda Roma İmparatorluğu\'nda icat edilip İpek Yolu\'yla Çin ve Amerika\'ya taşınmıştır', 'İlk yazı sistemi Güney Kutbu yakınlarındaki adalarda doğmuş, buzulların erimesiyle kıtalara eşit sürede dağılmıştır'], 'Bilim dünyasında yazının tamamen sıfırdan ve bağımsız icadı kesin olarak Mezopotamya (Sümer), Çin (Şang) ve Mezoamerika (Olmek/Maya) —ve büyük ölçüde Mısır— ile sınırlandırılır; diğer sistemler doğrudan aktarım veya uyaran yayılımıyla gelişmiştir.'),
  ('Devanagari yazısında bir ünsüz harfin bünyesindeki varsayılan kısa /a/ ünlüsünü susturarak onu saf ünsüz olarak okutmak için harfin altına konulan eğik çizgiye ne ad verilir?', 'Virama', ['Şirorekha', 'Anusvara', 'Visarga'], 'Sanskritçe "durma/dinlenme" anlamına gelen Virama (Hintçede Halant), ünsüzün doğal ünlüsünü iptal eder veya ünsüz kümeleri kurmaya yarar.'),
  ('Devanagari abugidasında kısa /i/ ünlüsünü gösteren "ि" (i-matra) işaretinin yazılış konumu ile okunuş sırası arasındaki ilginç özellik nedir?', 'Ünsüzden sonra okunmasına rağmen görsel olarak ünsüz harfin soluna (öncesine) yazılması', ['Ünsüzden önce okunmasına rağmen kelimenin en son harfinden sonraya eklenmesi', 'Yalnızca büyük harflerle başlayan özel isimlerin altına ters olarak çizilmesi', 'Hiçbir ünsüz harfe dokunmadan satırın en altında ayrı bir parantez içinde durması'], 'Devanagari ve birçok Brahmi kökenli abugidada ses diziliminde ünsüzden sonra gelen /i/ sesi (örneğin \'ki\'), görsel dizilimde ünsüzün sol tarafına yerleştirilir.'),
  ('Devanagari yazısında "k + ş" (क्ष) veya "t + r" (त्र) gibi ardışık ünsüz kümeleri (conjunct consonants) bir araya geldiğinde geleneksel olarak nasıl yazılır?', 'Ünsüzler virama etkisiyle kaynaşarak "samyuktakşara" adı verilen birleşik ligatürler oluşturur', ['İki ünsüz arasına zorunlu olarak üç adet Latin alfabesi tire işareti konulur', 'İlk ünsüz tamamen silinir ve okuyucunun onu cümlenin bağlamından tahmin etmesi beklenir', 'Ünsüzlerden birincisi satırın en başına, ikincisi ise sayfanın en altına taşınır'], 'Araya ünlü girmeyen ünsüz kümeleri Devanagari\'de yarım formlar veya özel kaynaşmış ligatürler (birleşik akşaralar) halinde tek bir grafik birim olarak yazılır.'),
  ('Güneydoğu Asya\'daki Tay (Tayland) ve Lao yazılarında okuma güçlüğü yaratan önemli yapısal özelliklerden biri aşağıdakilerden hangisidir?', 'Cümle içindeki kelimeler arasında boşluk bırakılmaması ve boşluğun yalnızca cümle/ifade sonlarında kullanılması', ['Metinlerin sağ alt köşeden başlayıp sola doğru çapraz basamaklar halinde yükselmesi', 'Yazıda hiçbir ünlü işaretinin bulunmaması ve tüm ünlülerin sadece el hareketleriyle gösterilmesi', 'Her kelimenin başında Çinceden alınmış zorunlu bir piktografik şehir simgesinin bulunması'], 'Pallava (Güney Hint) Brahmi kolundan gelen Tay, Lao ve Kmer yazılarında kelimeler bitişik dizilir (boşluk bırakılmaz) ve tonlamalar ünsüz sınıfları ile ton işaretlerinin birleşimiyle hesaplanır.'),
  ('MS 100 yılı civarında Doğu Han Hanedanı bilgini Xu Shen tarafından yazılan ve Çin karakterlerini 6 yapısal kategoriye (Liushu) ayırarak köklerine göre düzenleyen ilk kapsamlı sözlük hangisidir?', 'Şuowen Jiezi', ['Kangşi Sözlüğü', 'Hunmin Congım', 'Divânu Lügâti\'t-Türk'], 'Xu Shen\'in "Şuowen Jiezi" adlı eseri 9.000\'den fazla karakteri 540 radikal başlığı altında incelemiş ve "Liushu" (Altı Yazı İlkesi) kuramını sistematikleştirmiştir.'),
  ('Birbirlerinin konuşma dilini (örneğin Mandarin ile Kantonca) karşılıklı olarak hiç anlayamayan iki Çinlinin klasik veya standart yazılı bir metni okuyup anlaşabilmesini sağlayan temel etken nedir?', 'Logografik karakterlerin dar sesbirimlere değil doğrudan biçimbirim ve anlam birimlerine bağlı olması', ['Mandarin ve Kantonca lehçelerinde bütün kelimelerin tamamen aynı ses ve tonlarla telaffuz edilmesi', 'Çin yazısının her cümlenin altına İngilizce ve Rusça çevirileri zorunlu olarak eklemesi', 'Kantonca konuşanların okuma yazma öğrenirken yalnızca Kiril alfabesini kullanması'], 'Alfabetik yazılar telaffuz değiştikçe farklılaşırken, Çin logogramları anlam/morfem odaklı olduğu için "su (水)" karakteri Pekin\'de "shuǐ", Kanton\'da "seoi" diye okunsa da kağıt üzerinde aynı anlaşılır.'),
  ('Çin\'in Hunan eyaletindeki Jiangyong bölgesinde yüzyıllar boyunca yalnızca kadınlar arasında gizli bir dayanışma ve dertleşme aracı olarak yaşatılan fonetik hece yazısı hangisidir?', 'Nüşu (Kadın Yazısı)', ['Dongba (Rahip Yazısı)', 'Tangut (Batı Şia Yazısı)', 'Cürcen Yazısı'], 'Çince "kadın yazısı" anlamına gelen Nüşu, geleneksel eğitimden dışlanan kadınların eşarp, yelpaze ve kağıtlara işlediği zarif eşkenar dörtgen biçimli bir hece yazısıdır.'),
  ('Hiragana ve Katakana hece yazılarının her ikisi de Manyogana karakterlerinden türemiş olmasına rağmen görsel biçimlerinin farklılaşması tarihsel olarak nasıl gerçekleşmiştir?', 'Hiragana Çince karakterlerin bütünsel işlek el yazısı (caoshu) kıvrımlarından, Katakana ise karakterlerin sadece küçük bir köşesinin/parçasının yalıtılmasından doğmuştur', ['Hiragana Kore\'deki Kral Sejong\'un Hangıl alfabesinden, Katakana ise Moğolların dikey Uygur yazısından doğrudan alınmıştır', 'Hiragana samuray kılıçlarıyla taşlara kazındığı için yuvarlak, Katakana ise ipek kumaşa fırçayla sürüldüğü için köşeli kalmıştır', 'Hiragana yalnızca ünlü harflerden oluşurken Katakana yalnızca ünsüz harflerden oluşan bir ebced olarak tasarlanmıştır'], 'Heian döneminde saray kadınları arasında edebiyat dili olan Hiragana ("onna-de") karakterin tümünün akıcı el yazısıyla basitleştirilmesiyle; Katakana ("parça kana") ise Budist rahiplerin Çince metin kenarlarına karakterin tek bir parçasını not düşmesiyle gelişmiştir.'),
  ('Japoncadaki tek bir Kanji karakterinin (örneğin 山 - dağ) genellikle hem "san" gibi Çince kökenli bir okunuşa hem de "yama" gibi öz Japonca bir okunuşa sahip olması hangi terimlerle adlandırılır?', 'Çince kökenli okunuşa On\'yomi, öz Japonca karşılık okunuşuna ise Kun\'yomi denir', ['Çince kökenli okunuşa Hiragana, öz Japonca karşılık okunuşuna ise Katakana denir', 'Çince kökenli okunuşa Furigana, öz Japonca karşılık okunuşuna ise Romaji denir', 'Çince kökenli okunuşa Virama, öz Japonca karşılık okunuşuna ise Matra denir'], 'On\'yomi ("ses okuması") karakterin Çinceden ödünç alınan yaklaşık tarihsel telaffuzunu (Fuji-san), Kun\'yomi ("anlam okuması") ise o kavramın yerli Japonca kelimesini (yama) ifade eder.'),
  ('Japoncanın tarih boyunca Kanji\'yi tamamen terk edip yalnızca Hiragana hece yazısına geçmemesinin en güçlü dilbilimsel gerekçesi aşağıdakilerden hangisidir?', 'Japoncada çok fazla eşsesli (homofon) kelime bulunduğu için boşluksuz yazılan metinlerde Kanji\'nin anlam ayırt edici ve kelime sınırlarını gösterici işlev taşıması', ['Hiragana hece yazısının Japoncadaki ünlü ve ünsüz seslerin yarısından fazlasını yazmaya teknik olarak yetmemesi', 'Kanji karakterlerini yazmanın ilkokul çocukları için 46 harflik Hiragana tablosunu öğrenmekten çok daha kısa sürmesi', 'Uluslararası telif anlaşmalarının Japonca kitaplarda en az yüzde elli oranında Çince karakter kullanılmasını zorunlu kılması'], 'Japoncada ses envanteri dar olduğu için "kōshō" veya "kikan" gibi tek bir ses dizisi onlarca farklı kelimeye karşılık gelir; Kanji hem bu eşsesliliği anında çözer hem de boşluksuz cümlede kök ile eki görsel olarak ayırır.'),
  ('Dilbilimci Geoffrey Sampson\'ın Kore alfabesi Hangıl\'ı sıradan alfabelerden ayırarak "özelliksel yazı" (featural script) diye sınıflandırmasının nedeni nedir?', 'Harf şekillerinin rastgele olmayıp sesleri çıkarırken dil, diş, damak, dudak ve gırtlağın aldığı fiziksel konumu çizgisel olarak modellemesi', ['Her harfin doğadaki bir dağ, nehir veya hayvan türünün gerçekçi suluboya resminden sadeleştirilmiş olması', 'Yalnızca Kore sarayındaki şairlerin ses tonlarını müzik notası gibi beş çizgili porte üzerinde göstermesi', 'Kelimelerin okunuşunu değil, yalnızca o kelimenin ait olduğu toplumsal sınıfı ve nezaket derecesini belirtmesi'], 'Hangıl\'da örneğin ㄱ (/k, g/) dil kökünün damağı kapatmasını, ㄴ (/n/) dil ucunun üst diş etine değmesini, ㅁ (/m/) ağız şeklini gösterir; solukluluk gibi fonetik özellikler ise harfe düzenli bir çizgi eklenmesiyle (ㄱ -> ㅋ, ㄴ -> ㄷ -> ㅌ) türetilir.'),
  ('Hangıl hece bloklarının kuruluş kuralına göre hiçbir yazılı hece bloku doğrudan bir ünlü harfle (örneğin ㅏ /a/) başlayamaz; hece sesçe ünlüyle başlıyorsa bloğun başlangıç ünsüz konumuna ne yerleştirilir?', 'Başta ses değeri taşımayan (boş/sıfır ünsüz olan) daire biçimli İıng (ㅇ) harfi', ['Yalnızca yabancı kelimelerde kullanılan çift çizgili sert Hı (ㅎ) harfi', 'Çin karakterlerinden ödünç alınan küçük bir "insan" (人) radikali', 'Önceki kelimenin son ünsüzünü tekrar ettiren bir uzatma işareti'], 'Hangıl\'da daire şeklindeki ㅇ (ieung) harfi hece başında "sessiz yer tutucu" olarak kullanılarak blok simetrisini korur (아 = a), hece sonunda (batchim konumunda) ise genizsil /ŋ/ (ng) sesini verir (강 = gang).'),
  ('Vietnam\'da Fransız sömürge döneminde kabul edilen Latin tabanlı "Chữ Quốc Ngữ" alfabesinden önce, yerel Vietnamca kelimeleri yazmak için Çin karakterlerinin değiştirilip birleştirilmesiyle geliştirilen geleneksel logografik sistem hangisidir?', 'Chữ Nôm', ['Kharosthi', 'Linear B', 'Phags-pa'], 'Vietnam aydınları yüzyıllarca klasik Çince (Chữ Hán) yanında öz Vietnamca edebiyatı yazmak için Çince parçalarını yeni fono-semantik kombinasyonlarla birleştiren karmaşık "Chữ Nôm" sistemini kullanmış, daha sonra Cizvit misyoner Alexandre de Rhodes\'un katkısıyla gelişen Latin tabanlı Quốc Ngữ\'ye geçmiştir.'),
  ('Bir dildeki ortalama hece yapısının basit (yalnızca Ünsüz+Ünlü gibi açık heceler) veya karmaşık (str-, -kts gibi çoklu ünsüz salkımları) olması, o dil için hangi yazı sisteminin verimliliğini doğrudan etkiler?', 'Japonca gibi açık ve az sayıda hece tipine sahip dillere hece yazısı çok uygunken, İngilizce ve Gürcüce gibi karmaşık ünsüz salkımlı dillerde hece yazısı binlerce sembol gerektireceğinden alfabe çok daha verimlidir', ['Karmaşık ünsüz salkımlarına sahip diller yalnızca piktografik resim yazılarıyla eksiksiz yazılabilirken basit heceli dillerde alfabe kullanmak imkansızdır', 'Bir dilin ses ve hece yapısının kullanılan yazı sisteminin sembol sayısıyla hiçbir matematiksel veya pratik bağlantısı yoktur', 'Ünlü uyumu bulunan sondan eklemeli dillerde yalnızca ünsüzleri gösteren noktasız ebced sistemleri en az belirsizliği sağlar'], 'Japoncada yaklaşık 100 temel mora/hece olduğu için 46\'lık kana tablosu yeterlidir; oysa "strengths" gibi heceleri olan İngilizce için saf hece yazısı kurmak binlerce ayrı hece sembolü ezberlemeyi gerektirirdi.'),
  ('Batı Afrika\'da 1949 yılında Gine\'den Solomana Kante tarafından Manding dillerinin ortak edebi dili için icat edilen, tonlamaları bile özel işaretlerle gösteren sağdan sola alfabetik yazı hangisidir?', 'N\'Ko alfabesi', ['Ge\'ez abugidası', 'Bamum hece yazısı', 'Meroitik yazı'], '"Manding dillerinde \'diyorum ki\' anlamına gelen N\'Ko, sömürgecilerin Afrika dillerinin yazıya dökülemeyeceği iddiasını çürütmek üzere Solomana Kante\'nin tasarladığı yüksek hassasiyetli tam fonemik ve tonlamalı bir alfabedir.'),
  ('Kanada Yerli (İnuktitut) yazısında sembolü döndürerek ünlü değiştirme yöntemi, dilbilimsel sınıflandırmada neden saf hece yazısından ziyade "abugida" alt türüne dahil edilir?', 'Aynı ünsüzü paylaşan heceler birbirinden kopuk rastgele şekiller taşımayıp tek bir temel ünsüz geometrisinin sistematik yön değişimiyle kurulduğu için', ['Bu yazı sisteminde yalnızca ünsüz harfler yazılıp ünlülerin tamamı okuyucunun hayal gücüne bırakıldığı için', 'Metinler Hindistan\'daki Devanagari yazısı gibi üstten kesintisiz bir yatay çizgiyle birbirine bağlandığı için', 'Her geometrik şekil aslında tek bir sesi değil bir cümlenin tamamını anlatan bir ideogram olduğu için'], 'Saf hece yazısında (Hiragana: か ka, き ki, く ku) şekiller arasında görsel ortaklık yokken, Kanada sisteminde ünsüz kimliği sabit geometrik şekille korunur ve ünlü yönlendirmeyle sistematik olarak kodlanır.'),
  ('Dijital tipografide Arapça ve Devanagari gibi yazıların ekrana doğru çizdirilmesi ("complex text layout / shaping"), Latin veya Yunan alfabesine göre neden çok daha karmaşık yazılım motorları gerektirir?', 'Harflerin komşu harflere göre dinamik şekil değiştirmesi, ligatür kurması, yazım yönünün çift yönlü olabilmesi veya ünlü işaretlerinin harfin soluna/üstüne yeniden konumlanması nedeniyle', ['Arapça ve Devanagari harflerinin toplam sayısının Çin karakterlerinden on kat daha fazla (yüz binlerce) olması nedeniyle', 'Bilgisayar ekranlarındaki piksellerin yalnızca köşeli Roma harflerini gösterecek biçimde dikdörtgen üretilmesi nedeniyle', 'Bu yazı sistemlerinde kelimelerin her okunuşta rastgele renk ve boyut değiştirmesinin dilbilgisi kuralı olması nedeniyle'], 'Latin harfleri soldan sağa sabit kutular halinde yan yana dizilirken; Arapçada bağlamsal birleşme ve sağdan-sola/rakamlarda soldan-sağa çift yönlülük (BiDi), Devanagari\'de ise virama ligatürleri ve görsel yer değiştirme (i-matra) gelişmiş metin şekillendirme motorları gerektirir.'),
  ('Girit Adası\'nda bulunan, kilden yapılmış dairesel bir levhanın her iki yüzüne önceden hazırlanmış kalıplarla (mühürlerle) sarmal biçimde basılmış 241 işaretten oluşan eşsiz arkeolojik buluntu hangisidir?', 'Phaistos Diski', ['Rosetta Taşı', 'Kadeş Tableti', 'Siloam Yazıtı'], 'MÖ 2. binyıla tarihlenen Phaistos Diski, hareketli mühür/baskı fikrinin antik bir habercisi sayılmakla birlikte tekil bir buluntu olduğu için üzerindeki işaret sistemi bilimsel olarak doğrulanıp çözülememiştir.'),
  ('Adana\'nın Kadirli ilçesi yakınlarında bulunan ve üzerinde aynı metnin hem Fenike ebcediyle hem de Anadolu (Luvi) hiyeroglifleriyle yazılı olması sayesinde Luvi hiyerogliflerinin tam olarak çözülmesini sağlayan anıt hangisidir?', 'Karatepe-Aslantaş Çift Dilli Yazıtı', ['Yazılıkaya Açık Hava Tapınağı', 'Göbeklitepe T Biçimli Dikilitaşı', 'Gordion Tümülüsü Yazıtı'], 'Halet Çambel ve Helmuth Theodor Bossert\'in incelediği MÖ 8. yüzyıla ait Karatepe (Azatiwataya) çift dilli yazıtları, okunabilen Fenikece metin yardımıyla Anadolu hiyerogliflerinin kesin biçimde çözülmesini sağlamıştır.'),
  ('Türkçenin tarih boyunca Arap alfabesiyle (Osmanlı Türkçesi) yazıldığı dönemde yaşanan temel imla güçlüğünün dilbilimsel kaynağı nedir?', 'Türkçenin 8 ünlülü zengin ünlü uyumuna dayanan bir dil olmasına karşılık Arap ebcedinin ünlüleri göstermekte sınırlı kalması', ['Arap alfabesinde /b/, /d/, /l/, /m/ ve /n/ gibi temel dudak ve diş ünsüzlerini gösterecek hiçbir harfin bulunmaması', 'Türkçede bütün kelimelerin en az beş ünsüzle başlaması ve Arap yazısının yan yana iki ünsüze izin vermemesi', 'Arap yazısının sadece rakamları yazabilmesi ve fiil çekim eklerini kağıt üzerinde hiç gösterememesi'], 'Sami dillerinde anlam üçlü ünsüz kökte (k-t-b) taşındığı için ebced çok elverişlidir; ancak Türkçede "ol/öl, kol/köl/kul/kül" gibi anlam farklarını ünlüler belirlediğinden yalnızca Vav (و) ve Ye (ي) harfleri sekiz ünlüyü ayırt etmekte yetersiz kalmıştır.'),
  ('Sudan\'daki antik Kuş (Meroe) Krallığı\'nda MÖ 3. yüzyıldan itibaren Mısır hiyeroglif ve Demotik işaretlerinden esinlenerek geliştirilen, ses değerleri okunabildiği halde dili bilinmediği için metinleri tam anlaşılamayan yazı hangisidir?', 'Meroitik yazı', ['Ge\'ez yazısı', 'Kıpti yazısı', 'Tifinag yazısı'], 'İngiliz Mısırbilimci Francis Llewellyn Griffith 1911\'de Meroitik abugida/alfabenin ses değerlerini çözmüştür; yani kelimeleri seslendirebiliyoruz ancak Meroitik dilin bilinen yaşayan bir akrabası kesinleşmediği için anlamlarının çoğu hâlâ kapalıdır.'),
  ('Aynı dil ailesine mensup dillerin mutlaka aynı yazı sistemini kullanmadığını, farklı dil ailelerinden dillerin ise aynı yazı sistemini paylaşabildiğini gösteren en doğru örnek kümesi hangisidir?', 'Hint-Avrupa dillerinden İngilizce Latin, Rusça Kiril, Yunanca Yunan, Farsça Arap, Hintçe Devanagari yazısını kullanırken; farklı ailelerden Arapça (Sami), Farsça (Hint-Avrupa) ve Uygurca (Türk) Arap tabanlı yazıyı paylaşır', ['Sami dillerinin tamamı tarih boyunca yalnızca Çin karakterlerini kullanırken, Ural-Altay dillerinin tamamı yalnızca Maya hiyerogliflerini kullanmıştır', 'Bir dilin ait olduğu genetik dil ailesi değişmeden o dilin kullandığı alfabenin değiştirilmesi dilbilimsel olarak imkansızdır', 'Dünyada Latin alfabesini kullanan bütün diller Latin dilinden türemiş Roman dilleridir, başka hiçbir dil ailesi bu alfabeyi kullanamaz'], 'Dil (sözlü genetik yapı) ile yazı (kültürel-tarihsel kayıt aracı) birbirinden bağımsızdır; din, imparatorluk ve kültür havzaları farklı dil ailelerini aynı yazı şemsiyesinde toplayabildiği gibi akraba dilleri farklı alfabelere bölebilir.'),
  ('Pakistan\'ın ulusal dili Urduca ile Hindistan\'ın resmi dillerinden Hintçe günlük konuşma düzeyinde (Hindustani) büyük ölçüde karşılıklı anlaşılabilir ikiz diller olmasına rağmen yazılı metinlerinin birbirine tamamen yabancı görünmesinin nedeni nedir?', 'Urducanın İslam kültür havzası etkisiyle sağdan sola Nesta\'lik Arap-Fars yazısını, Hintçenin ise Sanskrit geleneğiyle soldan sağa Devanagari abugidasını kullanması', ['Urducanın yukarıdan aşağıya Çin logogramlarıyla, Hintçenin ise parmak uçlarıyla okunan kabartma Braille noktalarıyla yazılması', 'Hintçenin yalnızca ünsüz harflerden oluşan Fenike ebcedini, Urducanın ise Kral Sejong\'un Hangıl hece bloklarını kullanması', 'Urducada kelimeler arasında üçer santimetre boşluk bırakılırken Hintçede tüm harflerin tersten boustrophedon düzeninde dizilmesi'], 'Hintçe ve Urduca "tek konuşma tabanı, iki ayrı edebi/yazılı gelenek" (digrafi/sosyolinguistik ayrışma) olgusunun dünyadaki en çarpıcı örneğidir.'),
  ('Yazı sistemlerinin evrimi "resimden ideograma, oradan heceye ve en son alfabeye uzanan tek yönlü bir mükemmelleşme merdiveni" olarak görüldüğünde modern dilbilimciler bu görüşe neden eleştirel yaklaşır?', 'Çince, Japonca ve Devanagari gibi alfabetik olmayan sistemler kendi dillerinin morfolojik, eşseslilik ve kültürel ihtiyaçlarını son derece işlevsel karşıladığı ve her yazı sistemi kendi dil yapısıyla uyumlu avantajlar sunduğu için', ['Modern dilbilimciler alfabenin aslında MÖ 50.000 yılında icat edildiğini ve bütün resim yazılarının alfabenin bozulmuş hali olduğunu kanıtladığı için', 'Alfabe kullanan toplumlarda okuryazarlık oranının tarih boyunca her zaman logografik ve abugida kullanan toplumlardan daha düşük kaldığı için', 'Bilgisayar çağında klavyeler yalnızca Çince logogramları yazabildiği ve Latin harflerini dijital ekrana aktarmak teknik olarak imkansız olduğu için'], '19. yüzyılın "alfabe en üstün son aşamadır" şeklindeki çizgisel-evrimci önyargısı terk edilmiştir; morfem-hece yapılı Çince için Hanzi veya ek-kök ayrımı ve eşseslilik için Japoncada Kanji+Kana karma sistemi yüksek okuma hızı ve anlamsal netlik sağlamaktadır.'),
  ('Bir metinde karakterlerin bir kısmının çok vuruşlu karmaşık logogramlar, bir kısmının kıvrımlı zarif hece işaretleri, yabancı bir özel ismin ise köşeli hece işaretleriyle yazıldığı ve kelimeler arasında boşluk bırakılmadığı görülüyorsa bu metin hangi dile aittir?', 'Japonca', ['Korece', 'Vietnamca', 'Hintçe'], 'Modern Korece yalnızca Hangıl blokları (ve kelime arası boşluklar), Vietnamca Latin harfleri, Hintçe ise üst çizgili Devanagari kullanır; Kanji (karmaşık logogram) + Hiragana (kıvrımlı ekler) + Katakana (köşeli yabancı adlar) üçlüsünü boşluksuz birleştiren tek dil Japoncadır.'),
  ('Orhun alfabesinde "nt", "nç", "lt" (veya "ld") gibi çift ünsüz salkımlarını tek bir işaretle gösteren damgalara ne ad verilir?', 'Çift sesli (bileşik) ünsüz damgaları', ['Dudaksıl yuvarlak ünlü damgaları', 'Yarım ünsüz (akıcı) ayırıcı damgalar', 'Süreksiz sert patlayıcı damgalar'], 'Göktürk alfabesinde nt, nç, lt/ld gibi ünsüz çiftlerini tek başına karşılayan özel bileşik damgalar vardır.'),
  ('Orhun Yazıtları\'nın ilk tam tercümesini Thomsen\'in alfabeyi çözmesinin hemen ardından 1894 yılında yayımlayan Rus Türkolog kimdir?', 'Vasily Radloff', ['Nikolay İlminskiy', 'Aleksandr Samoyloviç', 'Sergey Malov'], 'Thomsen alfabeyi çözdükten hemen sonra Vasily Radloff, 1894\'te ilk tercüme denemesini hızla yayımlamıştır.'),
  ('Uygur alfabesinde bazı benzer harfleri (örneğin n ile a/e veya k ile g/ğ seslerini) birbirinden ayırt etmek için sonradan geliştirilen yardımcı uygulama nedir?', 'Harflerin üzerine veya yanına ayırıcı noktalar konulması', ['Her sözcüğün sonuna dikey çift çizgi eklenmesi', 'Kelime başındaki harflerin iki kat büyük yazılması', 'Ünlü harflerin kırmızı mürekkeple ayrıca renklendirilmesi'], 'Harf sayısının azlığından doğan karışıklığı azaltmak için Uygur yazısında zamanla noktalama sistemine başvurulmuştur.'),
  ('Fatih Sultan Mehmed\'in Uzun Hasan\'a karşı kazandığı Otlukbeli Zaferi sonrasında 1473\'te Şeyh Hasan Bey adına İstanbul\'da yazdırdığı yarlık hangi alfabeyle kaleme alınmıştır?', 'Uygur alfabesiyle', ['Göktürk alfabesiyle', 'Süryani alfabesiyle', 'Kiril alfabesiyle'], 'Fatih Sultan Mehmed\'in Otlukbeli Zaferi sonrası yayımladığı 1473 tarihli ünlü yarlığı Uygur harfleriyle yazılmıştır.'),
  ('Brahmi alfabesiyle yazılmış Eski Uygurca metinlerin Türk dil tarihi araştırmaları açısından taşıdığı en önemli sesbilimsel değer nedir?', 'Türkçenin o dönemdeki dar ve geniş yuvarlak ünlü ayrımlarını (o/ö, u/ü, e/é) ayrıntılı göstermesi', ['Türkçedeki ilk noktalama işaretlerinin tamamının bu alfabeyle icat edilmiş olması', 'Yalnızca askeri antlaşmalarda kullanıldığı için resmi devlet unvanlarını içermesi', 'Göktürk alfabesindeki 38 damganın doğrudan ata biçimlerini barındırması'], 'Ses değerleri zengin olan Brahmi yazısı, Uygur ve Arap yazılarının gizlediği o/u ve ö/ü gibi ünlü farklarını açıkça belgelemiştir.'),
  ('Doğu Türkistan\'da Hristiyanlığın Nasturi mezhebini benimseyen Türk topluluklarının mezar taşları ve dini metinlerinde kullandıkları alfabe hangisidir?', 'Süryani (Estrangelo) alfabesi', ['Grek (İyon) alfabesi', 'Latin (Gotik) alfabesi', 'Ermeni (Mesrop) alfabesi'], 'Nasturi Hristiyan Türkler, Süryani alfabesinin Estrangelo kolunu Türkçe metin ve mezar yazıtlarında kullanmışlardır.'),
  ('Karadeniz\'in kuzeyi ile Doğu Avrupa\'da yaşayan Musevi inancına mensup Karay (Karaim) Türkleri ile Hazarların bir kısmının kullandığı alfabe hangisidir?', 'İbrani alfabesi', ['Gürcü alfabesi', 'Brahmi alfabesi', 'Tibet alfabesi'], 'Museviliği benimseyen Karay Türkleri dini ve edebi metinlerini yüzyıllar boyunca İbrani alfabesiyle yazmışlardır.'),
  ('1851 yılında Vartan Paşa tarafından yazılan ve Türk edebiyatının ilk yerli roman denemelerinden sayılan "Akabi Hikayesi" hangi alfabeyle basılmıştır?', 'Ermeni alfabesiyle', ['Yunan alfabesiyle', 'Arap alfabesiyle', 'Fransız Latin alfabesiyle'], 'Vartan Paşa\'nın Türkçe kaleme aldığı Akabi Hikayesi, Ermeni harfli Türkçe geleneğinin en tanınmış edebi örneklerindendir.'),
  ('Osmanlı alfabesinde yalnız Türkçeye özgü geniz "n"si (ñ / nazal n) sesini göstermek amacıyla "kef" (ك) harfinin özel bir işlevi olarak adlandırılan harf türü hangisidir?', 'Kef-i nuni', ['Kef-i Arabi', 'Kef-i Farisi', 'Kef-i yayi'], '"Deniz, gönül, bin" gibi sözcüklerdeki geniz n\'si (ñ) Osmanlıcada sağır kef olarak bilinen kef-i nuni ile karşılanmıştır.'),
  ('Osmanlı Türkçesi imlasında "كورك" (kef-vav-re-kef) biçiminde yazılan tek bir kelimenin bağlama göre "kürk, kürek, gevrek, görk, görmek (kökü)" gibi farklı şekillerde okunabilmesi neyin sonucudur?', '"Vav" ve "kef" harflerinin birden fazla ünlü ve ünsüz ses değerini aynı anda taşımasının', ['Osmanlı Türkçesinde bütün fiil ve isim köklerinin eş sesli olarak türetilmesinin', 'Farsça tamlama kurallarının Türkçe kelimelerin son harfini düşürmesinin', 'Noktalama işaretlerinin Tanzimat sonrasında tamamen yürürlükten kaldırılmasının'], '"Vav" harfi o, ö, u, ü ve v seslerini; "kef" harfi ise k, g, ğ, ñ seslerini karşıladığı için tek yazım çoklu okumaya yol açmıştır.'),
  ('Tanzimat döneminde Arap harflerinin bitişik yazılmasından vazgeçilerek ayrı yazılmasını ve ünlülerin harflerle gösterilmesini savunan Azerbaycanlı aydın kimdir?', 'Mirza Fethali Ahundzade', ['İsmail Gaspıralı', 'Hüseyinzade Ali Turan', 'Ahmet Ağaoğlu'], 'Mirza Fethali Ahundzade, 1863\'te İstanbul\'a gelerek Sadrazam Fuat Paşa\'ya alfabe ıslahı projesini sunmuştur.'),
  ('Birinci Dünya Savaşı yıllarında ordudaki yazışmaları hızlandırmak amacıyla harflerin birbirine bitişmeden ayrı yazıldığı "Hatt-ı Cedid / Ordu Elifbası" uygulaması kimin girişimiyle denenmiştir?', 'Enver Paşa', ['Talat Paşa', 'Gazi Osman Paşa', 'Mithat Paşa'], 'Harflerin ayrı ayrı yazıldığı "Enveriye" veya "Hatt-ı Cedid" denemesi Enver Paşa\'nın öncülüğünde uygulanmış ancak savaş koşullarında terk edilmiştir.'),
  ('1926 yılında Sovyetler Birliği sınırları içindeki Türk topluluklarının ortak bir Latin esaslı alfabeye ("Birleştirilmiş Yeni Türk Alfabesi") geçme kararını aldıkları kongre hangi şehirde toplanmıştır?', 'Bakü', ['Taşkent', 'Kazan', 'Semerkant'], '1926\'da toplanan Birinci Bakü Türkoloji Kurultayı\'nda Türk halklarının Latin esaslı ortak alfabeye geçmesi kararlaştırılmıştır.'),
  ('Dil Encümeni\'nin ilk taslağında Türkçedeki "ç" ve "ş" sesleri için "ch" veya "sh" gibi çift harfli dizimler tartışılmışken Atatürk\'ün müdahalesiyle "ç" ve "ş"nin seçilmesi hangi yazım ilkesini güçlendirmiştir?', 'Her temel ses biriminin tek bir harfle gösterilmesi (birebir ses-harf uyumu) ilkesini', ['Arapça ve Farsça kökenli kelimelerin etimolojik kök imlasının korunması ilkesini', 'Avrupa dillerinden alınan kelimelerin özgün yazılışlarıyla Türkçeye aktarılması ilkesini', 'Ünsüz harflerin hece sonlarında okunmadan yazılmasına dayanan tarihsel imla ilkesini'], 'Çift harfli (digraf) gösterimler yerine ç, ş, ğ, ı, ö, ü gibi tek harflerin benimsenmesi tam fonetik yazımı sağlamıştır.'),
  ('1930\'ların sonunda Sovyetler Birliği\'ndeki Kazak, Kırgız, Özbek, Türkmen ve Tatar Türkleri için tek bir ortak Kiril alfabesi yerine her boya farklı ek harfler içeren 19-20 ayrı Kiril alfabesi düzenlenmesinin dilbilimsel ve kültürel sonucu ne olmuştur?', 'Lehçeler arasındaki karşılıklı yazılı anlaşılabilirlik zorlaşmış ve edebi dil birliği parçalanmıştır', ['Bütün Türk lehçelerinin tek bir standart yazı dilinde hızla birleşmesi sağlanmıştır', 'Eski Göktürk damgalarının tamamı Kiril harflerinin içine eksiksiz biçimde aktarılmıştır', 'Ünlü uyumu kuralları bütün Kıpçak ve Oğuz lehçelerinde tamamen ortadan kalkmıştır'], 'Aynı seslerin (örneğin ö, ü, ğ, ç, c) her Türk boyunda farklı Kiril işaretleriyle yazılması ortak yazılı iletişimi engellemiştir.'),
  ('1991 yılında Marmara Üniversitesi Türkiyat Araştırmaları Enstitüsü\'nde düzenlenen sempozyumda Türk cumhuriyetleri için önerilen "Ortak Türk Alfabesi" kaç harften oluşacak biçimde tasarlanmıştır?', '34 harf', ['29 harf', '38 harf', '24 harf'], 'Türkiye\'deki 29 harfe ä (ə), ñ, q, w, x harflerinin eklenmesiyle oluşturulan Ortak Türk Alfabesi 34 harfli olarak belirlenmiştir.'),
  ('34 harfli Ortak Türk Alfabesi\'nde Türkiye Türkçesi alfabesine ek olarak yer verilen "ä (ə), q, x, ñ, w" harfleri hangi ihtiyacı karşılamak üzere seçilmiştir?', 'Diğer Türk lehçelerindeki açık e, art damak k\'si, hırıltılı h, geniz n\'si ve çift dudak v\'si seslerini göstermek', ['İngilizce ve Fransızcadan giren teknik terimlerin özgün yabancı imlasını korumak', 'Arapça dini metinlerdeki ayın ve hemze seslerini Latin harfleriyle birebir yazmak', 'Rusçadan ödünç alınan kelimelerin Kiril alfabesindeki vurgularını işaretlemek'], 'Bu beş ek harf; Azerbaycan, Kazak, Özbek, Tatar ve Türkmen Türkçelerinde anlam ayırıcı olan özgün sesbirimleri karşılar.'),
  ('Yenisey Yazıtları\'ndaki damga biçimlerinin Kül Tigin ve Bilge Kağan yazıtlarındaki damgalara göre daha düzensiz ve çok varyantlı olması dil tarihçileri tarafından genellikle nasıl yorumlanır?', 'Yenisey yazıtlarının bir kısmının Orhun\'daki standartlaşmış resmi saray yazısından daha eski veya taşra geleneğine ait olduğu', ['Yenisey yazıtlarının Soğd tüccarlar tarafından Uygur harflerinden kopyalanarak sonradan uydurulduğu', 'Yenisey havzasındaki Türk boylarının ünlü harfleri tamamen reddeden bir ses sistemine sahip olduğu', 'Bu yazıtlardaki bütün metinlerin Moğol İmparatorluğu döneminde Cengiz Han tarafından yazdırıldığı'], 'Damga şekillerindeki çeşitlilik ve imla düzensizliği, Yenisey taşlarının bir bölümünün Orhun\'daki klasikleşmeden önceki evreyi yansıttığını gösterir.'),
  ('1999 yılında yayımlanan "Türk Dilinin Etimolojik Sözlüğü" adlı kapsamlı başvuru eserini hazırlayan Türk dilbilimci kimdir?', 'Hasan Eren', ['Şemseddin Sami', 'Ömer Asım Aksoy', 'Agop Dilaçar'], 'Prof. Dr. Hasan Eren\'in uzun yıllar süren araştırmalarının ürünü olan Türk Dilinin Etimolojik Sözlüğü 1999\'da yayımlanmıştır.'),
  ('13. yüzyıl öncesi Eski ve Orta Türkçe söz varlığını etimolojik açıdan inceleyen "An Etymological Dictionary of Pre-Thirteenth-Century Turkish" (1972) adlı temel eserin yazarı kimdir?', 'Sir Gerard Clauson', ['Vilhelm Thomsen', 'Armin Vambery', 'Jean Deny'], 'İngiliz Türkolog Sir Gerard Clauson\'ın 1972\'de yayımlanan etimolojik sözlüğü, erken dönem Türkçesi için en önemli başvuru kaynaklarındandır.'),
  ('Eski Türkçede tilki, kurt, kuş ve at dahil tüm canlıları kapsayan "keyik (geyik)" sözcüğünün ("yabani hayvan") standart Türkiye Türkçesinde yalnızca boynuzlu tek bir memeli türünü karşılaması nasıl açıklanır?', 'Genel tür adının tek bir hayvana özgülenmesiyle gerçekleşen anlam daralması', ['Özel bir yer adının bütün hayvan türlerine yayılmasıyla oluşan anlam genişlemesi', 'Yabancı bir dilden ses benzetmesiyle yapılan halk etimolojisi uyarlaması', 'Olumsuz çağrışımlı bir sıfatın saygınlık kazanmasıyla doğan anlam iyileşmesi'], 'Eski Türkçede "yabani olan her hayvan" (keyik) iken sadece "Cervidae" familyasındaki geyiği anlatması tipik bir anlam daralmasıdır.'),
  ('Moğolcadan Türkçeye geçen ve başlangıçta "yağmacı akıncı, başıbozuk öncü, çapulcu" gibi sert/olumsuz çağrışımlar da barındıran veya Farsça "çaker/nöker" gibi "hizmetkar" anlamındaki bazı unvanların zamanla yüksek saray rütbesine ("mareşal < at bakıcısı" örneğindeki gibi) dönüşmesi hangi olgudur?', 'Anlam iyileşmesi (rütbe ve değer yükselmesi)', ['Anlam kötüleşmesi (anlam düşmesi)', 'Halk etimolojisi (yakıştırma)', 'Ses düşmesi (aploloji)'], 'Frankça "at uşağı / ahır görevlisi" iken en yüksek askeri rütbe olan "mareşal" sözcüğü dünya dilbiliminde anlam iyileşmesinin en klasik örneğidir.'),
  ('Eski Türkçede yalnızca "çocuk, küçük yavru" anlamına gelen nötr bir sözcük olan "uşak" kelimesinin İstanbul ve standart Türkiye Türkçesinde "parayla tutulan erkek hizmetçi, başkasına boyun eğen kimse" gibi küçültücü bir anlama da kayması hangi olaydır?', 'Anlam kötüleşmesi', ['Anlam iyileşmesi', 'Halk etimolojisi', 'Ödünç çeviri'], 'Karadeniz ve Azerbaycan ağızlarında hala "çocuk" anlamını koruyan "uşak" kelimesinin standart dilde "hizmetçi, kul" anlamına düşmesi anlam kötüleşmesidir.'),
  ('Anadolu\'da Bizans döneminden kalan Yunanca "Eregli" (< Herakleia) yer adının "Erikli", "Sinasos" ya da "Makri" yer adlarının veya "Aydos" (< Aetos: kartal) kalesinin halk arasında "Ay-dost" biçiminde açıklanması etimoloji biliminde nasıl değerlendirilir?', 'Yer adlarında görülen halk etimolojisi', ['Tarihsel ses yasalarına dayalı düzenli ünsüz türemesi', 'İki farklı Türk lehçesi arasındaki edebi metin aktarması', 'Eski Göktürk alfabesinden kalan imla kalıntısı'], 'Yabancı kökenli yer adlarının halk tarafından Türkçe kelimelerle ("ay" ve "dost", "erik" vb.) anlamlandırılması toponimik halk etimolojisidir.'),
  ('Farsça "kâr-ban" (iş/ticaret koruyan kafile) sözcüğünün "kervan"a, "merd-i bân" (basamak) sözcüğünün "merdiven"e dönüşürken, Fransızca "contre-poids" ya da İngilizce "bulldog" yerine, Fransızca "couvre-lit" (yatak örtüsü) veya "fermoir" (toka/kilit) sözcüğünden "fermuar"ın halk ağzında "ferman" değil; İtalyanca "scontro / sconto" (iskonto) yanında, Arapça "mahrek" yerine Farsça "çâr-pâre" (dört parça) çalgı adının Türkçede "çarpana / çalpara" ("çalar para" çağrışımıyla) biçimini alması hangi olguyla açıklanır?', 'Halk etimolojisi', ['Büyük ünlü uyumunun yabancı kelimeleri tamamen reddetmesi', 'Anlam iyileşmesi yoluyla ticari terimin dini terime dönüşmesi', 'Kiril alfabesinden Latin alfabesine geçişteki harf hatası'], 'Farsça "çâr-pâre" (dört parça tahta zil) sözcüğü, Türkçe "çalmak" ve "para" kelimelerinin çağrışımıyla "çalpara" biçimine girmiştir.'),
  ('Aşağıdaki Türkçe sözcük ve kavramlardan hangisi Batı dillerindeki modelinden (İngilizce "brainwashing" veya Fransızca "guerre froide") birebir aktarılmış bir "ödünç çeviri" (kalk) örneğidir?', 'Soğuk savaş ve beyin yıkama', ['Karanfil ve fesleğen', 'Kaldırım ve pencere', 'Yoğurt ve pastırma'], '"Cold war / guerre froide" -> "soğuk savaş" ve "brainwashing" -> "beyin yıkama" ifadeleri yapısal ödünç çeviri örnekleridir.'),
  ('Türkçedeki "marangoz, şalter, şaryo" değil; "fidan, sınır, temel, anahtar, kilit, fener" sözcüklerinin ortak etimolojik köken dili aşağıdakilerden hangisidir?', 'Yunanca', ['Farsça', 'Sırpça', 'Soğdca'], 'Fidan, sınır (< synoron), temel, anahtar, kilit (< kleidi) ve fener (< phanari) sözcüklerinin tamamı Yunancadan Türkçeye geçmiş ödünçlemelerdir.'),
  ('Eski Türkçenin Orta Asya evresinde Çinceden ödünç aldığı kabul edilen ve Orhun/Uygur metinlerinde de izleri görülen sözcük grubu aşağıdakilerden hangisidir?', 'İnci (yinçü), tuğ, prenses anlamındaki kunçuy ve çay', ['Pencere, duvar, merdiven ve bahçe', 'İskele, fırtına, kalyon ve kadırga', 'Bilet, gişe, vagon ve istasyon'], 'Eski Türkçedeki "yinçü" (inci), "kunçuy" (prenses), "tuğ" ve daha geç dönemdeki "çay" sözcükleri Çince kökenli ödünçlemelerdir.'),
  ('13. yüzyıldaki Cengiz Han istilası sonrasında Türk yazı dillerine Moğolcadan geçen veya Türk-Moğol etkileşimiyle yayılan askeri ve idari sözcüklere aşağıdakilerden hangisi örnektir?', 'Kurultay, nöker, yasak (yasa), karakol ve şölen', ['Mektep, medrese, katip, defter ve kalem', 'Balyoz, konsolos, parlamento, senato ve bütçe', 'Rüzgar, asuman, mehtap, şafak ve gurup'], 'Kurultay, karakol, nöker (yoldaş/asker) ve şölen gibi terimler Moğolca üzerinden veya Türk-Moğol idari geleneğiyle yerleşmiştir.'),
  ('Türkçedeki "pulluk, kuluçka, vişne, çete, şapka, mazot" (bazıları Fransızca/Rusça/Balkan Slavcası aracılığıyla) sözcüklerinden özellikle "vişne, kuluçka, çete, kral, kraliçe" grubu hangi dil ailesinden Türkçeye girmiştir?', 'Slav dillerinden (Bulgarca, Sırpça, Rusça vb.)', ['Kelt dillerinden (İrlandaca ve Galce)', 'Sami dillerinden (İbranice ve Aramice)', 'Hint-Ari dillerden (Urduca ve Hintçe)'], 'Balkanlar ve Doğu Avrupa\'daki temaslar yoluyla vişne, kuluçka, çete ve kral (< Karl / korol) gibi sözcükler Slav dillerinden Türkçeye geçmiştir.'),
  ('Balkan dillerinde (Sırpça, Boşnakça, Bulgarca, Yunanca ve Arnavutça) yüzlerce hatta binlerce Türkçe ödünç sözcüğün ("börek, cezve, çorap, yastık, yorgan, tavan, boya, komşu" vb.) bulunmasının temel tarihsel nedeni nedir?', 'Balkanların yaklaşık beş yüzyıl boyunca Osmanlı İmparatorluğu idaresi ve şehir kültürü altında kalması', ['Balkan uluslarının tarih boyunca yalnızca Göktürk ve Uygur alfabelerini kullanmış olması', 'Slav ve Yunan dillerinin Ural-Altay dil ailesinin doğrudan birer alt kolu olması', '1928 Harf İnkılabı\'nın bütün Balkan ülkelerinde aynı gün yürürlüğe konulması'], 'Osmanlı dönemindeki uzun süreli ortak şehir yaşamı, zanaat, mutfak ve idare kültürü Balkan dillerinde "Turcism" (Türkizm) denilen zengin bir katman bırakmıştır.'),
  ('Türkçeden Sırpça, Boşnakça ve Bulgarcaya geçen sözcükler arasında yalnız öz Türkçe kelimeler ("börek, yatak, kaşık") değil, aslen Arapça ve Farsça olan pek çok kelimenin de ("saat, cep, bahçe, pencere, dükkân") bulunması etimolojide hangi kavramla açıklanır?', 'Aracı dil (verici dil) rolüyle dolaylı ödünçleme', ['Anlam daralması yoluyla kök sadeleşmesi', 'Yalnızca yazılı çeviriye dayanan ödünç çeviri', 'İç seste ünlü türemesiyle oluşan ikileme'], 'Arapça ve Farsça kökenli bu sözcükler Balkanlara doğrudan o dillerden değil, Osmanlı Türkçesinin ses ve anlam kalıbıyla "Türkçe üzerinden" (aracı dil olarak) geçmiştir.'),
  ('Macarcada tarım, hayvancılık ve devlet düzeniyle ilgili yüzlerce Eski Batı Türkçesi (Çuvaş-Bulgar tipi r/l Türkçesi) ödünç sözcüğün (örneğin Macarca "ökör" < öküz, "borjú" < buzağı, "alma" < elma, "arpa" < arpa, "búza" < buğday) bulunması neyi gösterir?', 'Macarların bugünkü yurtlarına göç etmeden önce Karadeniz\'in kuzeyinde Bulgar-Hazar Türkleriyle iç içe yaşadığını', ['Macarların 16. yüzyılda Kanuni Sultan Süleyman döneminde kendi dillerini tamamen unuttuğunu', 'Macarcanın Hint-Avrupa dil ailesinin Cermen koluna mensup bir dil olduğunu', 'Bu kelimelerin Macarcaya 20. yüzyıldaki turizm faaliyetleri sırasında geçtiğini'], 'Macarlar 9. yüzyıl öncesinde Karadeniz bozkırlarında Ogur (Bulgar) Türkleriyle yaşadıkları için Türkçedeki z/ş yerine r/l özellikli ("öküz" -> "ökör") eski alıntılar almışlardır.'),
  ('Arapçadan Türkçeye geçen "hukuk" (hak\'kın çoğulu), "evrak" (varak\'ın çoğulu), "evlat" (veled\'in çoğulu), "eşya" (şey\'in çoğulu) ve "ahlak" (hulk\'un çoğulu) sözcüklerinin Türkçede tekil anlamda veya üzerine tekrar "+lar/+ler" eki getirilerek ("evlatlar, evraklar") kullanılması etimolojik açıdan nasıl açıklanır?', 'Ödünçlenen yabancı çoğul kalıplarının hedef dilde dilbilgisel çoğulluk işlevini yitirip tekil kök gibi algılanmasıyla', ['Arapçada bu sözcüklerin hiçbir zaman tekil biçimlerinin var olmamış olmasıyla', 'Türkçedeki "+lar/+ler" ekinin aslında tekillik ve küçültme eki görevinde kullanılmasıyla', 'Anlam kötüleşmesi sonucunda bütün soyut kavramların somut nesne adına dönüşmesiyle'], 'Kaynak dildeki kırık çoğul (cem-i mükesser) kalıbı Türkçenin dilbilgisi sistemine geçmediği için kelime Türkçede tek bir sözlüksel birim (tekil ya da topluluk adı) sayılmıştır.'),
  ('Türkiye Türkçesindeki "güllâç" tatlısının adı etimolojik olarak hangi sözcük öbeğinin sesçe aşınıp kaynaşmasından doğmuştur?', 'Güllü aş', ['Gül ağacı', 'Gül ilacı', 'Gül ve aç'], 'Gül suyu katılarak yapılan yiyecek anlamındaki "güllü aş" tamlaması, tıpkı "sütlü aş > sütlaç" örneğindeki gibi kaynaşarak "güllaç" biçimini almıştır.'),
  ('Eski Türkçede "kadın / kayın" (dünür, evlilik bağıyla akraba) ve "katun / hatun" (hükümdar eşi, soylu hanım) sözcüklerinin Türkiye Türkçesindeki "kadın" kelimesiyle ilişkisi konusunda etimologların ortaya koyduğu temel açıklama nedir?', '"Hatun < katun" sözcüğünün t > d yumuşaması ve ünlü uyumuyla "kadın" biçimine evrildiği', ['"Kadın" kelimesinin 19. yüzyılda Fransızcadan ödünç çeviri yoluyla türetildiği', '"Kadın" sözcüğünün Arapça "kadim" (eski) sıfatının anlam daralmasına uğramış şekli olduğu', '"Kadın" ve "hatun" sözcüklerinin hiçbir tarihsel dönemde aynı anda kullanılmadığı'], 'Soğdca kökenli olduğu kabul edilen Eski Türkçe "katun" (kraliçe, bey eşi) sözcüğü bir koldan "hatun", diğer koldan t > d değişimiyle "kadın" biçimini almıştır.'),
  ('Türkiye Türkçesindeki "dedikodu", "uyurgezer", "biçerdöver" ve "konargöçer" gibi birleşik sözcüklerin etimolojik kuruluşunda hangi yapısal özellik görülür?', 'İki çekimli fiilin (geçmiş zaman veya geniş zaman/sıfat-fiil) bağlaçsız birleşerek kalıcı isim olması', ['Bir yabancı isimle Türkçe yardımcı fiilin ünlü düşmesi yoluyla kaynaşması', 'Yalnızca yansıma köklerin ikileme kurup sonuna yapım eki alması', 'Eski Uygurcadan kalan çift ünsüzlü damgaların ayrı okunması'], '"Dedi + kodu (koydu)" iki görülen geçmiş zaman çekiminin, "biçer + döver" ise iki geniş zaman/sıfat-fiil biçiminin kalıplaşmasıyla oluşmuş öz Türkçe birleşiklerdir.'),
  ('Bir dilbilimci bir Türk lehçesinde "dağ" yerine "taw", "sarı" (< sarığ) yerine "sarı", "ağlamak" (< ıglamak) yerine "jılaw" biçimlerini tespit ettiğinde etimolojik ses denklikleri açısından hangi sonuca ulaşır?', 'Söz konusu lehçenin Eski Türkçe art damak "g" sesini "w/u"ya ve kelime başı "y" sesini "j"ye çeviren Kıpçak (örneğin Kazak) grubuna ait olduğuna', ['Bu kelimelerin tamamının Çinceden halk etimolojisi yoluyla yeni ödünçlendiğine', 'İncelenen dilin Türkçeyle hiçbir akrabalığı bulunmayan Sami kökenli bir dil olduğuna', 'Sözcüklerin tamamında anlam kötüleşmesi ve ödünç çeviri gerçekleştiğine'], '"Tag > dağ / taw" ve "y- > j-" ses denklikleri karşılaştırmalı Türk etimolojisinde Oğuz (Türkiye) ve Kıpçak (Kazak/Kırgız) kollarını ayıran temel ölçütlerdir.'),
  ('Cumhuriyet döneminde Fransızca "ordinateur" / İngilizce "computer" kavramına karşılık olarak "bilgi" ve "saymak" köklerinden "bilgisayar" sözcüğünü türeterek Türkçeye kazandıran bilişim öncüsü ve akademisyen kimdir?', 'Aydın Köksal', ['Cahit Arf', 'Hulusi Behçet', 'Oktay Sinanoğlu'], 'Prof. Dr. Aydın Köksal, 1969 yılında "bilgisayar", "bilişim", "yazılım", "donanım" ve "bellek" gibi temel bilişim terimlerini Türkçe köklerden türetmiştir.'),
  ('Eski Anadolu Türkçesinde ve Yunus Emre\'nin şiirlerinde "cehennem" anlamında "uçmak" (cennet) karşıtı olarak kullanılan ve kökeni yine Soğdca "tamu" (cehennem) sözcüğüne dayanan kelime hangisidir?', 'Tamu', ['Kurgan', 'Balbal', 'Ötüken'], 'Eski Uygur ve Eski Anadolu Türkçesi metinlerinde "uçmak" (cennet) kelimesinin karşıtı olarak Soğdca kökenli "tamu" (cehennem) yaygın biçimde kullanılmıştır.'),
  ('Arapçada aynı "k-t-b" (yazmak) ünsüz çatısından iç ünlü değişimi ve eklerle türetilen "kitap, katip, mektep, mektup, kütüphane, kitabe, mukavele değil mükatebe" sözcüklerinin Türkçede birbirinden bağımsız kökler gibi algılanmasının nedeni nedir?', 'Arapçanın bükümlü (kök içi ünlü değiştiren) türetme sisteminin sondan eklemeli Türkçenin işlek kuralları içinde yer almaması', ['Bu sözcüklerin tamamının Türkçeye farklı yüzyıllarda Çince ve Rusçadan geçmiş olması', '1928 Yeni Türk Alfabesi\'nde "k, t, b" ünsüzlerinin yazımının yasaklanmış olması', 'Türkçede soyut ve somut isimlerin aynı cümle içinde kullanılmasının imkansız olması'], 'Arapça sülasi (üç ünsüzlü: k-t-b) bükümlü kök sistemi Türkçeye yabancı olduğundan, Türkçe konuşuru "kitap" ve "mektep"i türemiş değil ayrı kök sözcükler olarak algılar.'),
  ('Türkiye Türkçesinde "yaş" (ıslak), "yaş" (ömür yılı), "yaşam / yaşamak" ve "yaşarmak" sözcükleriyle "yeşil" ve "yaş" (taze sebze-meyve) kelimeleri arasındaki etimolojik bağ nasıl açıklanır?', '"Yaş" (taze, canlı, yeşil ot) kavramından her bahar yeşeren doğa döngüsüyle "bir yıllık ömür (yaş)" ve "yaşamak" kavramlarının geliştiği', ['"Yaş" sözcüğünün İngilizce "age" kelimesinden halk etimolojisiyle çevrildiği', '"Yeşil" kelimesinin Farsça, "yaşam" kelimesinin ise Yunanca kökenli sesteşler olduğu', 'Bu kelimeler arasında tarih boyunca hiçbir ses veya anlam ilişkisinin bulunmadığı'], 'Göçebe ve doğayla iç içe Türk kültüründe taze bitki/ot ("yaş", buradan "yaşıl > yeşil"), her bahar yeşermesi dolayısıyla "yıl/ömür" ("on yaş") ve "canlı kalmak" ("yaşa-mak") anlamlarını doğurmuştur.'),
  ('Türkçede "sağ" (yön: sağ taraf) ve "sol" kavramlarından "sağ" sözcüğünün aynı zamanda "canlı, diri, sağlıklı, esen" ve "sağlam" anlamlarını taşıması etimoloji ve kültür tarihinde hangi olguyla bağdaştırılır?', 'Pek çok dilde (Latince dexter, İngilizce right vb.) "sağ" kavramının güç, doğruluk, iyilik ve sağlıkla özdeşleştirilen olumlu anlam alanına sahip olmasıyla', ['"Sağ" kelimesinin yalnızca süt "sağmak" fiilinden anlam kötüleşmesi yoluyla türemiş olmasıyla', 'Göktürk alfabesinde sol yönün kutsal sayılıp sağ yönün uğursuz kabul edilmesiyle', '"Sağlam" sözcüğünün Fransızcadan ödünç çeviri (kalk) olarak alınmasıyla'], 'Eski Türkçede "sağ" (sağlam, sağlıklı, saf, iyi, sağ el/yön) hem fiziksel esenliği hem de uğurlu/güçlü sayılan yönü karşılayan köklü bir kavramdır.'),
  ('Türkiye Türkçesinde "armağan" ve "konuk" kavramlarıyla ilişkili söz varlığı içinde, bugün yalnız "kardeş" kelimesinde yaşayan "karın" kökü düşünüldüğünde "kardeş" sözcüğünün etimolojik açılımı nedir?', 'Karın + daş (aynı anne karnını paylaşan / karındaş)', ['Kan + eş (aynı kanı taşıyan eş)', 'Kara + taş (kara taş gibi sağlam dost)', 'Karşı + daş (karşılıklı duran kimse)'], '"Kardeş" sözcüğü, ortaklık bildiren "+daş" ekiyle kurulmuş "karındaş" (aynı karından doğan) kelimesinin orta hece düşmesi ve ünlü incelmesiyle oluşmuş biçimidir.'),
  ('Eski Türkçede "ot" (ateş; örn. "od"), "ot" (bitki, çayır; ayrıca ilaç -> "otacı": hekim) sözcüklerinin Eski Türkçe döneminde birbirinden nasıl ayırt edildiği (ve Türkiye Türkçesinde neden "od" / "ot" izi bıraktığı) etimolojik sesbilimde nasıl açıklanır?', '"Ateş" anlamındaki sözcüğün uzun ünlülü ("ōt > od"), "bitki/ilaç" anlamındaki sözcüğün ise kısa ünlülü ("ot") olmasıyla', ['Birinin yalnızca Göktürk alfabesiyle, diğerinin yalnızca Kiril alfabesiyle yazılmasıyla', '"Ot" (bitki) kelimesinin İtalyancadan, "od" (ateş) kelimesinin Rusçadan ödünçlenmesiyle', 'İki kelimenin arasına her zaman üç nokta konularak telaffuz edilmesiyle'], 'Ana Türkçedeki birincil uzun ünlüler, ünlüden sonra gelen t sesini Oğuzcada yumuşatmıştır: *ōt > od (ateş, örn. "odun"), kısa ünlülü *ot > ot (bitki, örn. "otlak").'),
  ('Türkiye Türkçesinde "gelin" sözcüğünün etimolojik kökeni dilbilimciler tarafından hangi Türkçe fiil köküyle açıklanır?', 'Aileye ve baba ocağına dışarıdan yeni katılan kişiyi anlatan "gel-" (gelmek) fiiliyle', ['Düğün alayında ata binmeyi anlatan "ger-" (germek) fiiliyle', 'Arapça "kale" sözcüğünün anlam iyileşmesine uğramış biçimiyle', 'Farsça "gül" (çiçek) isminin sonuna eklenen küçültme ekiyle'], 'Türk aile yapısında erkeğin baba evine yeni "gelen" aile üyesini ifade etmek üzere "gel-" fiilinden "+in" yapım ekiyle "gelin" sözcüğü türetilmiştir.'),
  ('Bir kelimenin etimolojisini belirlerken yalnızca bugünkü görünüşüne ve yüzeysel ses benzerliğine bakarak (örneğin İngilizce "day" ile Türkçe "ay" veya "Amazon" ile "amma uzun" arasında bağ kurarak) hüküm vermek neden bilimsel etimolojiye aykırıdır?', 'Kelimenin en eski yazılı metinlerdeki biçimlerini ve kurallı tarihsel ses denkliklerini kanıtlamadan kurulan benzerlikler rastlantısal yanılgı (sahte etimoloji) ürettiği için', ['Bilimsel etimolojide iki farklı dildeki kelimelerin karşılaştırılması kesin olarak yasaklandığı için', 'Yalnızca Arap ve Kiril alfabesiyle yazılmış kelimelerin kökeni araştırılabildiği için', 'Sözcüklerin anlamlarının yüz yılda bir tamamen tersine dönmesi zorunlu bir yasa olduğu için'], 'Bilimsel etimoloji rastgele ses benzeşimlerine değil, kelimenin kronolojik metin tanıklıklarına, biçimbilimsel kurallara ve düzenli ses yasalarına dayanır.'),
  ('Osmanlı Türkçesinden günümüze ulaşan "selamünaleyküm" değil; Arapça "inşaallah" (Allah dilerse) ve "maşaallah" (Allah\'ın dilediği şey ne güzel) ifadelerinin yanı sıra, "Allah\'a ısmarladık" vedalaşma sözünün konuşma dilinde hızlı söyleyişle (büzülme/hece yutumu) hangi biçime kadar kısaldığı görülür?', 'Allahaısmarladık > Alasmaladık', ['Günaydın > Tünaydın', 'Merhaba > Merhabalar', 'Hoşça kal > Güle güle'], '"Allah\'a ısmarladık" (seni Allah\'a emanet ettik) cümlesi, günlük konuşma dilinde hece aşınması (aploloji ve büzülme) yoluyla "alasmaladık" biçimine kadar kısalabilmektedir.'),
  ('Türkiye Türkçesinde "önceki gün, geçmiş gün" anlamında kullandığımız "dün" zaman zarfı etimolojik olarak Eski Türkçedeki hangi sözcüğün ses ve anlam değişimine uğramış biçimidir?', '"Gece" anlamına gelen "tün" sözcüğünün', ['"Dönmek" fiilinin emir kipi çekiminin', '"Düğün" isminin hece düşmesine uğramış şeklinin', 'Farsça "dünya" sözcüğünün kısaltılmış kökünün'], 'Eski Türkçede "gece" demek olan "tün" sözcüğü ("tünle": geceleyin), Oğuzcada önses ötümlüleşmesiyle (t- > d-) "dün" olmuş ve "geride kalan gece -> bir önceki gün" anlamını kazanmıştır.'),
  ('Aşağıdaki eşleştirmelerden hangisinde sözcüğün geçirdiği etimolojik/anlambilimsel olay YANLIŞ belirtilmiştir?', '"Canavar" (< Farsça can-aver: canlı) — Anlam iyileşmesi', ['"Yavuz" (< Eski Türkçe yabız: kötü, fena) — Anlam iyileşmesi', '"Oğlan" (< Eski Türkçe oglan: her cinsiyetten evlat) — Anlam daralması', '"Gökdelen" (< İngilizce skyscraper) — Ödünç çeviri'], 'Farsça "canlı varlık" anlamındaki "can-aver"in "yırtıcı korkunç yaratık" olması anlam iyileşmesi değil, tam tersine anlam kötüleşmesidir.'),
  ('Modern çeviribilimde "biçimsel eşdeğerlik" (formal equivalence) ve "devingen/dinamik eşdeğerlik" (dynamic equivalence) ayrımını ortaya koyan kuramcı kimdir?', 'Eugene Nida', ['Noam Chomsky', 'Ferdinand de Saussure', 'Leonard Bloomfield'], 'Amerikalı dilbilimci ve çeviribilimci Eugene Nida, kaynak metnin biçimine odaklanan biçimsel eşdeğerlik ile alıcıdaki etkiye odaklanan dinamik eşdeğerlik kuramını geliştirmiştir.'),
  ('Çeviribilimde bir çeviri eyleminin şekillenmesinde en belirleyici etkenin çevirinin "amacı ve işlevi" olduğunu savunan Hans J. Vermeer\'in kuramı hangi adla bilinir?', 'Skopos kuramı', ['Evrensel dilbilgisi kuramı', 'Sesbilimsel karşılaştırma kuramı', 'Bağımlılık dilbilgisi kuramı'], 'Yunanca "amaç/hedef" anlamına gelen "Skopos" kavramından adını alan kuram, Hans J. Vermeer tarafından geliştirilmiş olup çeviri stratejisini erek metnin işlevinin belirlediğini savunur.'),
  ('Lawrence Venuti\'nin çeviri stratejilerinde kaynak kültürün özgünlüğünü koruyarak okura yabancı bir metin okuduğunu hissettirme yaklaşımına ne ad verilir?', 'Yabancılaştırma (foreignization)', ['Yerlileştirme (domestication)', 'Sözcüksel fosilleşme (fossilization)', 'Fonetik benzeşme (assimilation)'], 'Venuti, metni erek kültürün kalıplarına eritmeye "yerlileştirme" (domestication), kaynak kültürün dilsel ve kültürel izlerini görünür kılmaya ise "yabancılaştırma" (foreignization) adını vermiştir.'),
  ('Roman Jakobson\'un ünlü sınıflandırmasında bir dilsel göstergenin aynı dil içindeki başka sözcüklerle yeniden ifade edilmesine (açımlama/özetleme) ne ad verilir?', 'Diliçi çeviri (intralingual translation)', ['Dillerarası çeviri (interlingual translation)', 'Göstergelerarası çeviri (intersemiotic translation)', 'Eşzamanlı kabin çevirisi (simultaneous interpreting)'], 'Jakobson çeviriyi üçe ayırır: diliçi (aynı dilde yeniden ifade), dillerarası (bir dilden başka dile asıl çeviri) ve göstergelerarası (romanın filme/resme uyarlanması).'),
  ('Bir edebi romanın sinema filmine, tiyatro oyununa veya bale eserine uyarlanması Roman Jakobson\'un çeviri sınıflandırmasında hangi kavrama karşılık gelir?', 'Göstergelerarası çeviri (intersemiotic translation)', ['Diliçi çeviri (intralingual translation)', 'Sözcüksel öyküntüleme (lexical calque)', 'Biçimbirimsel harf çevirisi (transliteration)'], 'Sözel dil göstergelerinin sözel olmayan gösterge dizgelerine (sinema, müzik, resim) aktarılması göstergelerarası çeviridir.'),
  ('İngilizce "solicitor" sözcüğü Birleşik Krallık hukuk sisteminde hangi mesleği ifade eder ve hangi yanlış anlamla karıştırılmamalıdır?', 'Dava hazırlığı ve hukuki danışmanlık yapan avukat demektir; ABD\'deki "seyyar satıcı/talep eden" anlamıyla veya "solist" ile karıştırılmamalıdır.', ['Yalnızca opera sahnesinde tek başına şarkı söyleyen baş solist demektir; mahkeme mübaşiri ile karıştırılmamalıdır.', 'Belediye meclisinde bütçe denetimi yapan mali müşavir demektir; vergi müfettişi ile karıştırılmamalıdır.', 'Parlamentoda yasa tasarılarını oylamaya sunan meclis başkanı demektir; noter katibi ile karıştırılmamalıdır.'], 'İngiliz İngilizcesinde "solicitor" müvekkillerle doğrudan görüşüp hukuki işlemleri yürüten avukattır; Amerikan İngilizcesinde ise kapı kapı dolaşıp satış/bağış isteyen kişiyi de ifade edebilir.'),
  ('İngilizce "miserable" sıfatı ile Fransızcadan Türkçeye de geçmiş edebi algı (Victor Hugo - Sefiller / Les Misérables) karşılaştırıldığında günlük İngilizcedeki "I feel miserable today." cümlesi ne anlatır?', 'Bugün kendimi çok mutsuz, keyifsiz ve kötü hissediyorum.', ['Bugün tüm mal varlığımı kaybettim ve sokakta dileniyorum.', 'Bugün başkalarına karşı son derece cimri ve acımasız davrandım.', 'Bugün bulaşıcı ve ölümcül bir hastalığa yakalandığımı öğrendim.'], 'Modern İngilizcede "miserable" çoğunlukla "çok mutsuz, keyifsiz, berbat (hava/ruh hali)" anlamında kullanılır; mutlak maddi yoksulluk için "destitute" veya "impoverished" tercih edilir.'),
  ('İngilizce "extravagant" sıfatı "His extravagant lifestyle led him into debt." cümlesinde hangi anlamı taşır?', 'Savurgan / aşırı lüks ve müsrif', ['Sıra dışı derecede yaratıcı ve sanatsal', 'Toplumdan kopuk ve içe kapanık', 'Son derece tutumlu ve hesaplı'], 'Türkçede bazen yalnızca "sıra dışı/ilginç" gibi algılansa da İngilizcede "extravagant" gereğinden çok para harcayan, müsrif, savurgan anlamına gelir.'),
  ('İngilizce "pretend" fiili ile Fransızca "prétendre" (veya Türkçe "iddia etmek" beklentisi) arasındaki yalancı eşdeğerlik ilişkisi nasıldır?', 'İngilizce "pretend" öyle olmadığı halde öyleymiş gibi davranmak (-mış gibi yapmak) demektir; Fransızca "prétendre" ise hak iddia etmek / ileri sürmek anlamındadır.', ['İngilizce "pretend" bilimsel bir tezi kanıtlamak demektir; Fransızca "prétendre" ise çocukça şaka yapmak anlamındadır.', 'İngilizce "pretend" önceden tahmin etmek demektir; Fransızca "prétendre" ise geçmişi unutmak anlamındadır.', 'İngilizce "pretend" bir törene katılmak demektir; Fransızca "prétendre" ise bir sözleşmeyi feshetmek anlamındadır.'], '"He pretended to be asleep." (Uyuyormuş gibi yaptı.) örneğinde görüldüğü gibi İngilizcede "pretend" rol yapmak, -mış gibi görünmektir; "iddia etmek" İngilizcede "claim"dir.'),
  ('İngilizce "resume" fiili ile "résumé" (Amerikan İngilizcesinde isim) sözcükleri Türkçedeki "özet" beklentisiyle karşılaştırıldığında hangisi doğrudur?', 'Fiil olan "resume" ara verilen bir işe kaldığı yerden devam etmek, isim olan "résumé" ise özgeçmiş (CV) demektir; metin özeti için "summary" kullanılır.', ['Hem fiil hem isim biçimi yalnızca akademik bir makalenin giriş özetini yazmak anlamına gelir.', 'Fiil olan "resume" bir işten istifa etmek, isim olan "résumé" ise emeklilik dilekçesi demektir.', 'Fiil olan "resume" baştan tekrar silip yazmak, isim olan "résumé" ise mahkeme tutanağı demektir.'], 'Fransızcada "résumer" özetlemek iken, İngilizcede "to resume" (kesintiden sonra) yeniden başlamak/sürdürmek fiilidir; isim olan "résumé" ise iş başvurularındaki özgeçmiştir.'),
  ('Çeviribilimde "kısmi yalancı eşdeğerler" (partial false friends) ile "tam yalancı eşdeğerler" (total false friends) arasındaki temel fark nedir?', 'Kısmi yalancı eşdeğerler çok anlamlı olup en az bir anlamda örtüşürken diğer anlamlarda ayrışır; tam yalancı eşdeğerlerin ise hiçbir ortak güncel anlamı yoktur.', ['Kısmi yalancı eşdeğerler yalnızca yazılışı benzeyen, tam yalancı eşdeğerler ise yalnızca okunuşu benzeyen sözcüklerdir.', 'Kısmi yalancı eşdeğerler sadece deyimlerde görülürken tam yalancı eşdeğerler yalnızca özel isimlerde görülür.', 'Kısmi yalancı eşdeğerler aynı dil içindeki eş seslilerdir; tam yalancı eşdeğerler yapay dillerdeki türetmelerdir.'], 'Örneğin İngilizce "character" ile Türkçe "karakter" kişilik anlamında örtüşür (gerçek eşdeğer yönü), ancak "roman/film kişisi" veya "harf/simge" kullanımlarında bağlamsal farklar doğabilir; "fabric/fabrika" veya Almanca "Gift" / İngilizce "gift" ise tam yalancı eşdeğerdir.'),
  ('Uluslararası bir konferansta Türkçe konuşan bir delegenin konuşmasını kabindeki birinci çevirmen İngilizceye çevirmekte, Çince ve İspanyolca kabinlerindeki çevirmenler ise Türkçe bilmedikleri için bu İngilizce çeviriyi dinleyerek kendi dillerine aktarmaktadır. Bu uygulamaya sözlü çeviribilimde ne ad verilir?', 'Röle çeviri (relay interpreting) ve kullanılan İngilizceye pivot dil', ['Ardıl fısıltı çevirisi ve kullanılan İngilizceye ölü kaynak dil', 'Göstergelerarası çeviri ve kullanılan İngilizceye yerel lehçe', 'Yazılıdan sözlüye çeviri ve kullanılan İngilizceye yapay kod'], 'Kaynak dili doğrudan bilmeyen kabinlerin ortak bir ara kabinin (pivot language) çıktısını kaynak alarak hedef dillere eşzamanlı çeviri yapmasına röle (relay) çeviri denir.'),
  ('İngilizce bir akademik metindeki "Subsequent studies actually invalidated the previous hypothesis." cümlesini Türkçeye en doğru şekilde aktaran seçenek hangisidir?', 'Daha sonraki araştırmalar, önceki hipotezi gerçekte geçersiz kıldı.', ['Alt düzeydeki çalışmalar, güncel hipotezi kısmen doğruladı.', 'Eşzamanlı deneyler, olası varsayımı tesadüfen ortadan kaldırdı.', 'Önceki araştırmalar, mevcut kuramı nihayetinde destekledi.'], '"Subsequent" daha sonra gelen/izleyen ("sub-" ön eki nedeniyle "alt düzey" sanılmamalıdır), "actually" ise gerçekte/aslında demektir.'),
  ('Fransızca ve İngilizce bilen bir çevirmen İngilizce "The new library has a large lecture hall." cümlesindeki "lecture" sözcüğünü Fransızca "lecture" (okuma) etkisiyle yanlış çevirmemek için hangi karşılığı seçmelidir?', 'Konferans / ders anlatımı', ['Sessiz okuma saati', 'Kitap ciltleme atölyesi', 'Yabancı dil sözlüğü'], 'Fransızca "lecture" okuma eylemi iken İngilizce "lecture" üniversite dersi veya halka açık akademik konferans/konuşma demektir.'),
  ('İtalyanca öğrenen bir çevirmen, İtalyanca "camera" (oda), "fattoria" (çiftlik) ve "morbido" (yumuşak) sözcüklerinin İngilizcedeki benzerleriyle ("camera", "factory", "morbid") oluşturduğu yalancı eşdeğerliği göz önüne alarak "La camera nella fattoria ha un letto morbido." cümlesini nasıl çevirmelidir?', 'Çiftlikteki odada yumuşak bir yatak var.', ['Fabrikadaki fotoğraf makinesinin hastalıklı bir merceği var.', 'Kameriyedeki üretim tesisinde sert bir kanepe bulunuyor.', 'Stüdyodaki atölyede karanlık ve kasvetli bir yatak var.'], 'İtalyancada "camera" oda, "fattoria" çiftlik (fabrika=fabbrica), "morbido" ise yumuşak (İngilizce "morbid" ise hastalıklı/ölümcül düşünceli) demektir.'),
  ('Almanca "aktuell" (güncel), "sensibel" (hassas/duyarlı), "sympathisch" (sevimli/cana yakın) ve "Fabrik" (fabrika) sözcükleri ile Türkçe ve İngilizcedeki karşılıkları birlikte incelendiğinde tarihsel-dilbilimsel açıdan hangi çıkarıma ulaşılır?', 'Türkçe bu kavramları Fransızca/kıta Avrupası anlamlarıyla ödünçlediği için Almanca ve Fransızca ile uyumlu, İngilizce ile ise yalancı eşdeğer konumundadır.', ['İngilizce bu sözcükleri doğrudan Osmanlı Türkçesinden aldığı için zamanla ses kaymasına uğratmıştır.', 'Almanca ve İngilizce Batı Germen dilleri olduğundan bu dört sözcüğün anlamları her iki dilde de yüzde yüz aynıdır.', 'Türkçedeki bu sözcükler İkinci Dünya Savaşı sonrasında Amerikan İngilizcesinden öyküntü yoluyla türetilmiştir.'], 'Kıta Avrupası dillerinde (Fransızca actuel, sensible, sympathique, fabrique; Almanca aktuell, sensibel, sympathisch, Fabrik) anlamlar Türkçedeki ödünçlemelerle paraleldir; İngilizcede ise Latince/Fransızca köklü bu kelimeler farklı anlamsal evrim geçirerek hem kıta dillerine hem Türkçeye göre yalancı eşdeğer olmuştur.'),
  ('Bir hukuk metninde geçen İngilizce "sentence" sözcüğü dilbilgisinde "cümle" anlamına gelirken "The judge pronounced a ten-year prison sentence." bağlamında "mahkumiyet hükmü / ceza" anlamına gelmektedir. Öte yandan İngilizce "juror" ile Türkçe "jüri", "bar" ile "baro" ilişkileri düşünüldüğünde çevirmenin "sentence" kelimesini burada "cümle" diye çevirmesi hangi tür hatadır?', 'Çok anlamlılık (polysemy) ve terimsel bağlamı göz ardı etme hatası', ['Diller arası fonetik transkripsiyon ve harf çevirisi hatası', 'Ardıl çeviride not alma simgelerini yanlış okuma hatası', 'Hedef dilde yerelleştirme yaparken para birimini dönüştürmeme hatası'], 'Aynı dil içinde birden fazla anlamı olan "sentence" sözcüğünün genel dildeki ilk anlamını (cümle) hukuk terimi bağlamına (hüküm/ceza) yanlış taşımak çok anlamlılık ve uzmanlık alanı bağlamını göz ardı etme hatasıdır.'),
  ('Ardıl (konsekütif) çeviride kullanılan profesyonel not alma tekniği (Jean-François Rozan ilkeleri) hakkında aşağıdakilerden hangisi doğrudur?', 'Sözcükleri tam cümleler halinde steno gibi yazmak yerine fikirleri, mantıksal bağlaçları, okları ve simgeleri dikey düzlemde not almaya dayanır.', ['Konuşmacının ağzından çıkan her kelimeyi kaynak dilde eksiksiz biçimde stenografi alfabesiyle satır satır kaydetmeyi şart koşar.', 'Yalnızca rakamları ve özel isimleri ezberleyip not kağıdına hiçbir simge veya kısaltma yazmamayı öğütler.', 'Notların mutlaka üçüncü bir ara dilde (Latince veya Esperanto) tam dilbilgisel kurallarla yazılmasını zorunlu tutar.'], 'Ardıl çeviri not alma tekniği stenografi değildir; belleği desteklemek amacıyla kavramları, özne-nesne ilişkilerini ve geçiş bağlaçlarını dikey/kademeli oklar ve evrensel sembollerle hızla kağıda dökmeye dayanır.'),
  ('Görsel-işitsel çeviri türlerinden görme engelliler için yapılan "sesli betimleme" (audio description) uygulaması Roman Jakobson\'un kuramsal çerçevesinde neden "göstergelerarası çeviri" sayılır?', 'Ekrandaki görsel eylem, yüz ifadesi ve mekan göstergelerini diyalog boşluklarında sözel dil göstergelerine dönüştürdüğü için', ['İngilizce diyalogları Fransızca altyazıya yazılı biçimde eksiksiz aktardığı için', 'Eski Osmanlıca bir romanı günümüz Türkiye Türkçesine sadeleştirerek uyarladığı için', 'Konferans konuşmacısının ses tonunu kabin mikrofonuyla dinleyicilere yükselterek ilettiği için'], 'Sesli betimlemede sözel olmayan görsel imgeler (jestler, kostümler, manzara) sözel anlatıma çevrilir; bu da gösterge dizgeleri arası (intersemiotic) bir aktarımdır.'),
  ('"The sympathetic physician gave sensible advice about the actual effects of the drug, and the patient eventually recovered." cümlesini Türkçeye çeviren dört adaydan hangisi tüm yalancı eşdeğer ve terim engellerini aşarak kusursuz bir çeviri üretmiştir?', 'Anlayışlı hekim, ilacın gerçek etkileri hakkında mantıklı tavsiyelerde bulundu ve hasta sonunda iyileşti.', ['Sempatik fizikçi, ilacın güncel etkileri konusunda hassas öğütler verdi ve hasta tesadüfen iyileşti.', 'Sevimli doktor, ilacın olası yan etkileri üzerine duygusal tavsiyeler verdi ve hasta muhtemelen taburcu oldu.', 'Şefkatli eczacı, ilacın aktüel sonuçları hakkında akıllıca uyarılarda bulundu ve hasta geçici olarak düzeldi.'], 'Sympathetic=anlayışlı/şefkatli, physician=hekim/doktor, sensible=mantıklı, actual=gerçek, eventually=sonunda/nihayetinde karşılıklarının tümünü doğru birleştiren tek seçenek birincisidir.'),
];
